def _load_artifact(skill, names):
    directory = Path(skill['source'])
    role = skill.get('role')
    searches = [(content_root() / skill['id'], names), (directory, names)]
    if role:
        searches = [(content_root() / ROLE_CONTENT[skill['id']], names),
                    (content_root() / skill['id'], names),
                    (directory, tuple(name.replace('.json', '.' + role + '.json') for name in names)),
                    (directory / 'knowledge' / role, names)]
    for base, file_names in searches:
        for name in file_names:
            path = base / name
            if not path.is_file() or not _allowed(path):
                continue
            try:
                data = json.loads(_text(path))
                if not isinstance(data, (dict, list)):
                    raise ValueError('expected an object or array')
                return data, path, None
            except (ValueError, TypeError) as exc:
                return None, path, 'Unreadable content: ' + str(exc)
    return None, None, None

def _path(raw, directory, artifact_dir=None):
    if not raw or not isinstance(raw, str) or '\x00' in raw:
        return None
    raw = raw.replace('\\', '/')
    path = Path(raw)
    if '..' in path.parts:
        return None
    candidates = [path] if path.is_absolute() else [directory / path]
    if not path.is_absolute():
        if artifact_dir:
            candidates.append(artifact_dir / path)
        candidates.extend([Path(api.FOUNDRY_ROOT) / path, discovery_roots()[2] / path])
    return next((p.resolve() for p in candidates if p.is_file() and _allowed(p)
                 and p.suffix.lower() in TEXT_TYPES and not any(
                     part.startswith('.') for part in p.relative_to(p.anchor).parts
                     if part not in ('.agents', '.claude', '.codex'))), None)

def _allowed(path):
    roots = (*discovery_roots(), content_root())
    return any(_inside(path, root) for root in roots)

def _trusted_origin(raw, skill):
    """A role may cite these exact originals; no user-home/root expansion."""
    if skill['id'] not in ROLE_CONTENT or not isinstance(raw, str):
        return None
    candidate = Path(raw.replace('\\', '/'))
    if not candidate.is_absolute() or '..' in candidate.parts:
        return None
    approved = [(root / rel, root) for root in
                (CODE_ROOT, Path(api.FOUNDRY_ROOT).parent / 'Anchor')
                for rel in ANCHOR_PROVENANCE]
    global_dir = Path.home() / '.claude'
    approved.append((global_dir / 'AGENTS.md', global_dir))
    for exact, root in approved:
        if (candidate == exact and _inside(candidate, root) and candidate.is_file()
                and candidate.resolve() == root.resolve() / exact.relative_to(root)):
            return candidate.resolve()
    return None

def _combined_display(skill, resources):
    """Foundry-owned foundry-skill-display/v1 handoff; canonical sources stay live.

    Anchors use the controlled reader. Historical examples use only their exact
    immutable snapshots; current sources retain visible freshness checks.
    """
    data, path, error = _load_artifact(skill, ('maps.json',))
    if data is None:
        return None, [error] if error else []
    if not isinstance(data, dict) or data.get('schema') != 'foundry-skill-display/v1' or data.get('skill_id') != skill['id']:
        return None, ['Unsupported or different-skill maps.json handoff']
    for field in ('sources', 'anchors', 'resources'):
        if not isinstance(data.get(field), list):
            return None, [field + ' must be an array in maps.json']
    for field, child in (('knowledge', 'nodes'), ('process', 'steps'), ('process', 'edges')):
        if not isinstance(data.get(field), dict) or not isinstance(data[field].get(child), list):
            return None, [field + '.' + child + ' must be an array in maps.json']
    issues, links = [], {}
    sources = {s.get('id'): s for s in data.get('sources', []) if isinstance(s, dict)}
    declared = {sid: _declared_source(source, skill, path.parent) for sid, source in sources.items()}
    for anchor in data.get('anchors', []):
        if not isinstance(anchor, dict):
            issues.append('Invalid source anchor')
            continue
        source = sources.get(anchor.get('source_id'), {})
        target, provenance, source_error = declared.get(anchor.get('source_id'),
                                                       (None, {}, 'Undeclared source'))
        spec = {'path': source.get('origin'), 'line': anchor.get('start'), 'sha256': source.get('sha256')}
        link = (_anchor_link(spec, skill, path.parent, resources, declared_path=target, provenance=provenance)
                if target else {'label': 'Source unavailable', 'problem': source_error})
        if link and link.get('href'):
            start, end = anchor.get('start'), anchor.get('end')
            if isinstance(start, int) and isinstance(end, int) and 1 <= start <= end <= len(_text(target).splitlines()):
                excerpt = '\n'.join(_text(target).splitlines()[start - 1:end])
                if anchor.get('sha256') and hashlib.sha256(excerpt.encode()).hexdigest() != anchor['sha256']:
                    link['problem'] = 'Source changed: anchored excerpt differs'
            else:
                link['problem'] = 'Invalid source range'
        if not link:
            link = {'label': 'Source unavailable', 'problem': 'Missing original source'}
        if link.get('problem'):
            issues.append(link['problem'] + ' · ' + str(anchor.get('source_id')) + ' / ' + str(anchor.get('id')))
        links[anchor.get('id')] = link
    categories = {'Reusable material': 'material', 'References': 'references', 'Other skills': 'skills', 'Tools': 'tools'}
    project_id = _review_project_id() if any(r.get('target') for r in data['resources'] if isinstance(r, dict)) else None
    for row in data.get('resources', []):
        if not isinstance(row, dict):
            issues.append('Invalid Library resource')
            continue
        link = links.get(row.get('anchor_id'), {})
        if not link.get('href'):
            issues.append('Library target missing: ' + str(row.get('id')))
            continue
        backing = next((r for r in resources if r['id'] == link.get('resourceId')), {})
        resources.append({**backing, 'id': row.get('id'), 'title': row.get('title'),
                          'category': categories.get(row.get('category'), 'material'),
                          'description': row.get('summary', ''), 'problem': link.get('problem'),
                          'href': _library_target(row.get('target'), path.parent, project_id) or backing['href'],
                          'sourceHref': backing['href'],
                          'frequency': _frequency(row, skill, path.parent), 'library': True})
    flow = data.get('process') if isinstance(data.get('process'), dict) else {}
    steps = []
    for row in flow.get('steps', []):
        if not isinstance(row, dict):
            issues.append('Invalid process step')
            continue
        aa = [links[a] for a in row.get('anchors', []) if a in links]
        steps.append({**row, 'description': row.get('summary'), 'anchorLinks': aa,
                      'codeLink': aa[0] if row.get('code_status') == 'anchored' and aa else
                          {'label': 'instructions-only', 'note': 'Session work; no code on this path.'},
                      'instructionLink': aa[-1] if row.get('instruction_status') == 'anchored' and aa else
                          {'label': 'no-separate-instruction', 'note': 'See the program source.'}})
        if not aa:
            issues.append('No process sources: ' + str(row.get('id')))
    knowledge = data.get('knowledge') if isinstance(data.get('knowledge'), dict) else {}
    nodes = [{**n, 'name': n.get('title'), 'parent': n.get('parent_id')}
             for n in knowledge.get('nodes', []) if isinstance(n, dict)]
    disagreements = [{**d, 'sourceLinks': [links[a] for a in d.get('anchors', []) if a in links]}
                     for d in flow.get('disagreements', []) if isinstance(d, dict)]
    return {'source': str(path), 'qualification': data.get('refinement') or 'Walkthrough awaiting human review.',
            'steps': steps, 'edges': [{**e, 'from': e.get('source'), 'to': e.get('target'),
                                      'sourceLink': links.get(e.get('anchor_id'))}
                                     for e in flow.get('edges', []) if isinstance(e, dict)],
            'exits': flow.get('terminals', []),
            'disagreements': disagreements, 'nodes': nodes, 'issues': issues,
            'observedExamples': [{**e, 'sourceLinks': [links[a] for a in e.get('anchors', []) if a in links]}
                                 for e in data.get('observed_examples', []) if isinstance(e, dict)],
            'usageAudit': data.get('usage_audit')}, issues

def select_model(family, catalog):
    if family not in FAMILIES:
        raise PolicyUnavailable(str(family), "unknown model family")
    rows = sorted(catalog, key=lambda item: item["rank"])
    if not rows:
        raise PolicyUnavailable(family, "no available model")
    if family == "chatgpt" and len(rows) > 1 and rows[0]["rank"] == rows[1]["rank"]:
        raise PolicyUnavailable(family, "latest model ranking is ambiguous; refresh subscription capabilities")
    chosen = rows[0]
    initial_model = chosen["model"]
    initial_evidence = chosen["evidence"]
    by_name = {row["model"]: row for row in rows}
    visited = set()
    while chosen.get("upgrade"):
        target = chosen["upgrade"]
        if isinstance(target, dict):
            target = target.get("model") or target.get("id")
        if target in visited:
            raise PolicyUnavailable(family, "cyclic catalog upgrade metadata")
        visited.add(chosen["model"])
        if target not in by_name:
            raise PolicyUnavailable(family, "recommended model upgrade is unavailable")
        chosen = by_name[target]
    try:
        effort = highest_effort(chosen["efforts"])
    except ValueError as error:
        raise PolicyUnavailable(family, str(error), code="unsupported_effort") from error
    result = {"policy_version": POLICY_VERSION, "requested_policy": dict(DEFAULT_POLICY),
              "family": family, "model": chosen["model"], "effort": effort,
              "selection_evidence": initial_evidence + ("+provider_upgrade" if initial_model != chosen["model"] else ""), "model_attested": False}
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:/-]{0,199}", result["model"]):
        raise PolicyUnavailable(family, "catalog model identity has unsupported characters")
    if initial_evidence == "provider_catalog_order":
        result["warning"] = "Provider-recommended catalog order; frontier ranking is not explicitly attested."
    return result

def get_engine(cdir, general=False, tid=None, create=True):
    if general:
        tid = str(tid or "1")
        if not re.fullmatch(r"\d{1,6}", tid):
            return None
        if create and tid not in _load_terms(cdir):
            return None
    key = cdir + (f"||general||{tid}" if general else "")
    with ENGINES_LOCK:
        if key not in ENGINES:
            if not create:
                return None
            if sum(1 for e in ENGINES.values() if e.alive()) >= MAX_LIVE_ENGINES:
                return None
            ENGINES[key] = Engine(cdir, permission_mode=CONFIG["permission_mode"],
                                  fake=CONFIG["fake"], steward=CONFIG["steward"],
                                  general=general, tid=tid if general else None)
        return ENGINES[key]

def handle_post(cdir, verb, body):
    if verb == "refinement-accept":
        from steward_cockpit.refinement_client import update
        import uuid
        current = campaign.read_refinement(cdir)
        if not current or not current.get("ok"):
            return {"ok": False, "error": "refinement-state-unavailable"}, 409
        sl = current["state"]["slices"].get(str(body.get("step_id")), {})
        presentation = next((p for p in sl.get("presentations", []) if p["id"] == body.get("presentation_id")), {})
        member = next((m for m in presentation.get("members", []) if m["product_id"] == body.get("product_id")), None)
        if not member or member["revision_id"] != body.get("revision_id") or member["hash"] != body.get("hash"):
            return {"ok": False, "error": "approval-version-mismatch"}, 409
        target = (Path(cdir) / member["path"]).resolve()
        if not target.is_relative_to(Path(cdir).resolve()) or not target.is_file() or hashlib.sha256(target.read_bytes()).hexdigest() != member["hash"]:
            return {"ok": False, "error": "approval-artifact-changed"}, 409
        result = update(cdir, {"action": "accept", "operation_id": str(uuid.uuid4()), "expected_seq": current["sequence"],
            "step_id": body["step_id"], "presentation_id": presentation["id"], "member_product_id": member["product_id"],
            "complete_current": True, "human": {"explicit": True, "source_message":
                "Authenticated cockpit: Done with " + member["product_id"] + "; exact revision " + member["revision_id"]}})
        if result.get('committed') is True and not result.get('ok'):
            result={**result,'ok':True,'warning':'Approval saved; the derived collection needs repair.'}
        if result.get("ok"):
            # W4 (2026-09-28): the correction set is PROPOSED in the foreground, never applied (his Q2); a failed
            # composition rides on the acceptance's answer as repair_error so the card can say no set was proposed;
            # the horizon follows, so its stamp covers the proposal event too (Grok W4)
            from steward_cockpit import repair as _repair
            rp = _repair.propose(cdir, body["step_id"], presentation["id"], background=False)
            if not (isinstance(rp, dict) and rp.get("ok")):
                result = {**result, "repair_error": str((rp or {}).get("error") or "repair_failed"), "repair_message": str((rp or {}).get("message") or "")[:200]}
            elif rp.get("appended"):
                result = {**result, "repair_proposed": {"proposal_id": rp.get("proposal_id"), "count": rp.get("count")}}
            from steward_cockpit import horizon as _horizon
            _horizon.refresh(cdir, "accepted")      # W3 (2026-09-28): the line follows the acceptance, at once
        return result, 200 if result.get("ok") else 409
    if verb == "refinement-close":
        from steward_cockpit.refinement_client import update
        import uuid
        current = campaign.read_refinement(cdir)
        if not current or not current.get("ok"):
            return {"ok": False, "error": "refinement-state-unavailable"}, 409
        result = update(cdir, {"operation_id": str(uuid.uuid4()), "expected_seq": current["sequence"],
            "action": "close", "step_id": body.get("step_id"), "presentation_id": body.get("presentation_id"),
            "human": {"explicit": True, "source_message": "Authenticated cockpit: Done with this slice; named presentation " + str(body.get("presentation_id"))}})
        if result.get('committed') is True and not result.get('ok'):
            result={**result,'ok':True,'warning':'Completion saved; the derived collection needs repair.'}
        return result, 200 if result.get("ok") else 409
    if verb == "refinement-update":
        from steward_cockpit.refinement_client import update
        result = update(cdir, body)
        return result, 200 if result.get("ok") else 409
    if verb == "refinement-open":
        # An explicit authenticated cockpit click, not a GET/prefetch receipt.
        # Anchor authenticates this route before dispatch. Verify exact bytes
        # before recording which frozen member the user chose to open.
        from steward_cockpit.refinement_client import update
        current = campaign.read_refinement(cdir)
        if not current or not current.get("ok"):
            return {"ok": False, "error": "refinement-state-unavailable"}, 409
        state = current["state"]
        step = state["slices"].get(str(body.get("step_id")))
        presentation = next((p for p in (step or {}).get("presentations", []) if p["id"] == body.get("presentation_id")), None)
        member = next((m for m in (presentation or {}).get("members", []) if m["product_id"] == body.get("product_id")), None)
        if not member:
            return {"ok": False, "error": "unknown-presentation-member"}, 409
        root = Path(cdir).resolve()
        target = (root / member["path"]).resolve()
        if not target.is_relative_to(root) or not target.is_file():
            return {"ok": False, "error": "containment-refused"}, 409
        if hashlib.sha256(target.read_bytes()).hexdigest() != member["hash"]:
            return {"ok": False, "error": "artifact-hash-mismatch"}, 409
        pending = next((request for request in step.get("review_requests", []) if request.get("presentation_id") == presentation["id"]), {})
        import uuid
        result = update(cdir, {"action": "view", "operation_id": str(uuid.uuid4()),
            "expected_seq": current["sequence"], "step_id": body["step_id"],
            "presentation_id": presentation["id"], "member_product_id": member["product_id"],
            "hash": member["hash"], "request_id": pending.get("id") if pending.get("presentation_id") == presentation["id"] else None,
            "session_id": str(body.get("session_id") or "cockpit"), "source": "cockpit-user-open"})
        if result.get("ok"):
            result["path"] = member["path"]
            result["hash"] = member["hash"]
        return result, 200 if result.get("ok") else 409
    if verb == "notebook-register":
        import anchor_notebooks
        try:
            return anchor_notebooks.register(cdir, source=body.get("source"),
                what=body.get("what"), step=body.get("step", ""),
                regenerate=body.get("regenerate") is True), 200
        except (ValueError, OSError) as exc:
            return {"ok": False, "error": str(exc)}, 409
    if verb == "drain-all":
        # 2026-08-25 hardening (review finding #1): the restart drain runs in a SEPARATE
        # process, so it can never see this service's live ENGINES — the in-process leg
        # was a structural no-op. The drain now POSTs here and THE SERVICE parks its own
        # engines: stop() commits a dirty steward tree and closes the proc; resume stays
        # seamless. Report distinguishes parked / already-idle — never a vacuous empty.
        report = {"parked": [], "idle": [], "errors": []}
        for key, eng in list(ENGINES.items()):
            try:
                if eng.alive():
                    eng.stop()
                    report["parked"].append(str(key))
                else:
                    report["idle"].append(str(key))
            except Exception as e:
                report["errors"].append(f"{key}: {type(e).__name__}: {e}")
        report["ok"] = not report["errors"]
        return report, 200
    if verb == "status-ack":
        # 2026-08-25 (elegance S-batch): render receipt from the pane — never
        # spawns an engine (create=False); a dead engine just means no receipt.
        eng = get_engine(cdir, bool(body.get("general")),
                         str(body.get("term") or "") or None, create=False)
        if eng is None:
            return {"ok": False, "error": "no live engine"}, 404
        return eng.record_status_ack(str(body.get("at") or "")), 200
    if verb == "say":
        # W5 (High Seat, 2026-09-26): a Campaign verb spoken on the Campaign record (move ... to tier n, add a part
        # to ..., make ... an initiative, park ... until ..., unpark ..., what needs me) is compiled by the engine's
        # act table and applied by the Campaign's own writer; the answer is its receipt with undo. Only the engine's
        # word that it is NOT a Campaign verb hands the text to the steward: a failed compile or a writer error
        # answers a refusal here, never a model turn.
        if not body.get("question_id") and not isinstance(body.get("refinement_context"), dict):
            from steward_cockpit.campaign_say import is_campaign_folder, say_campaign
            if is_campaign_folder(cdir):
                _goal = str(body.get("goal") or "").strip() or None
                spoken = say_campaign(cdir, str(body.get("text") or ""), goal=_goal)
                if spoken is not None:
                    if _goal and spoken.get("ok"):
                        note_goal_receipt(cdir, _goal, str(body.get("text") or ""), str(spoken.get("receipt") or spoken.get("say") or ""))
                    return spoken, (200 if spoken.get("ok") else 400)
        context = body.get("refinement_context")
        _refined_turn = False
        if isinstance(context, dict):
            from steward_cockpit.refinement_client import update
            import uuid
            current = campaign.read_refinement(cdir)
            if not current or not current.get("ok"):
                return {"ok": False, "error": "refinement-state-unavailable"}, 409
            feedback_id = str(uuid.uuid4())
            result = update(cdir, {"operation_id": feedback_id, "expected_seq": current["sequence"],
                "action": "feedback", "step_id": context.get("step_id"), "feedback_id": feedback_id,
                "source_message": str(body.get("text", "")), "base_presentation_id": context.get("presentation_id"),
                "changes": [{"id": "change-" + feedback_id, "scope": context.get("product_id") or "slice", "directive": "require", "text": str(body.get("text", ""))}],
                "elegance": {"mode": "RC6", "source": "User selected Refine this slice", "reason": "Apply the user's requested changes within this slice; assess new elements before adding scope."}})
            if not result.get("ok"):
                return result, 409
            from steward_cockpit import horizon as _horizon
            _horizon.refresh(cdir, "refined")       # W3 (2026-09-28): the line moves when the feedback is recorded
            _refined_turn = True
        eng = get_engine(cdir, bool(body.get("general")),
                         str(body.get("term") or "") or None)
        if eng is None:
            return {"ok": False, "error": "no such session / cap hit"}, 404
        result = (eng.say(body.get("text", ""), question_id=body["question_id"]) if body.get("question_id")
                  else eng.say(body.get("text", ""), goal=(str(body.get("goal") or "").strip() or None)))
        if _refined_turn:
            # W3 (Grok's hold): the turn's reply may have written the line — derive it again so the turn's own
            # sentence never stands over the stamped derivation
            from steward_cockpit import horizon as _horizon2
            _horizon2.refresh(cdir, "refined")
        return result, 200 if result.get("ok") else 409
    if verb == "code_job":
        # R3 (steward responsiveness, 2026-10-04): the steward hands real work to a code job and stays free to talk
        from steward_cockpit import code_jobs as _cj
        action = body.get("action") or "list"
        if action == "start":
            eng = get_engine(cdir)
            out = _cj.start(cdir, body.get("repo") or "", body.get("brief") or "", body.get("check") or "",
                            engine_factory=lambda wt: get_engine(wt, general=True, tid="1"),
                            steward=(eng.steward if eng else ""))
            if out.get("ok") and eng is not None:
                eng._emit({"t": "sys", "text": "code job %s started on %s (best model, full effort); the steward stays free to talk" % (out["job"], body.get("repo"))})
            return out, (200 if out.get("ok") else 400)
        if action == "stop":
            return _cj.stop(cdir, body.get("job"), engine_lookup=lambda wt: get_engine(wt, general=True, tid="1", create=False)), 200
        return {"ok": True, "jobs": list(_cj.read_jobs(cdir).values())[-20:]}, 200
    if verb == "engine":
        eng = get_engine(cdir, bool(body.get("general")),
                         str(body.get("term") or "") or None)
        if eng is None:
            return {"ok": False, "error": "no such session"}, 404
        action = body.get("action")
        if action == "wake":
            ok, why = eng.wake(fresh=bool(body.get("fresh")))
            return {"ok": ok, "why": why}, 200
        if action == "stop":
            eng.stop(); return {"ok": True}, 200
        if action in ("drive_on", "drive_off"):
            eng.set_drive(action == "drive_on"); return {"ok": True, "drive": eng.drive}, 200
        if action == "switch":
            return eng.switch_cli(body.get("cli", "")), 200
        if action == "take_now":
            # R1 (2026-10-04): his queued message goes now - interrupt the running turn, then wake on the queue
            return eng.take_now(), 200
        if action == "interrupt":
            # codex-discipline-2026-09-15 Wave 1.3: Stop turn (not park).
            return eng.interrupt_turn(str(body.get("reason") or "stopped by John")[:120]), 200
        return {"ok": False, "error": "unknown action"}, 400
    if verb == "open":
        target = os.path.realpath(os.path.join(cdir, body.get("path", "")))
        if not target.startswith(os.path.realpath(cdir) + os.sep):
            return {"ok": False, "error": "outside the effort"}, 400
        if os.path.splitext(target)[1].lower() not in OPENABLE_EXT:
            return {"ok": False, "error": "that file type is not openable here"}, 400
        if not os.path.isfile(target):
            return {"ok": False, "error": "file not found"}, 404
        try:
            os.startfile(target); return {"ok": True}, 200
        except Exception as e:
            return {"ok": False, "error": str(e)}, 500
    if verb == "term_new":
        with TERMS_LOCK:
            terms = _load_terms(cdir)
            tid = str(max([int(k) for k in terms] or [0]) + 1)
            terms[tid] = {"label": "terminal " + tid,
                          "created": time.strftime("%Y-%m-%d %H:%M"),
                          "archived": False}
            _save_terms(cdir, terms)
        return {"ok": True, "tid": tid}, 200
    if verb in ("term_archive", "term_restore"):
        tid = str(body.get("tid", ""))
        to_stop = None
        with TERMS_LOCK:
            terms = _load_terms(cdir)
            meta = terms.get(tid)
            if not meta:
                return {"ok": False, "error": "unknown terminal"}, 404
            if verb == "term_archive":
                live = ENGINES.get(cdir + f"||general||{tid}")
                if live and live.alive():
                    to_stop = live
                meta["archived"] = True
            else:
                meta["archived"] = False
            _save_terms(cdir, terms)
        if to_stop is not None:
            to_stop.stop()
        return {"ok": True}, 200
    if verb == "upload":
        return _upload(cdir, body)
    if verb == "new_effort":
        return _new_effort(cdir, body)
    return {"ok": False, "error": "unknown"}, 404

def act(project, body):
    """Dispatch one act from the page; every answer is a receipt sentence, ok or refused."""
    body = body if isinstance(body, dict) else {}
    a = str(body.get("act") or "")
    if a not in ACTS:
        return _no("no such act")
    try:
        if a == "move_tier":
            return move_tier(project, body.get("step"), body.get("tier"), body.get("order"))
        if a == "rank":
            return rank(project, body.get("step"), "up" if body.get("direction") == "up" else "down")
        if a == "rename":
            return rename(project, body.get("step"), body.get("name"))
        if a == "date":
            return date(project, body.get("step"), body.get("due"))
        if a == "park":
            return park(project, body.get("step"), body.get("waiting_on"))
        if a == "unpark":
            return unpark(project, body.get("step"))
        if a == "flag":
            return flag(project, body.get("step"), True)
        if a == "unflag":
            return flag(project, body.get("step"), False)
        if a == "tick":
            return tick(project, body.get("step"))
        if a == "add":
            return add(project, body.get("initiative"), body.get("kind"), body.get("text"), body.get("due"), body.get("project_id"))
        if a == "promote":
            return promote(project, body.get("seed"), body.get("tier"), body.get("area"), body.get("done_when"))
        if a == "retag":
            return retag(project, body.get("step"), body.get("initiative"))
        if a == "seat":
            return seat(project, body.get("step"), body.get("seat"), body.get("position"))
        if a == "home":
            return home(project, body.get("step"))
        if a == "new_goal":
            return new_goal(project, body.get("text"), body.get("tier"), body.get("area"), body.get("done_when"))
        if a == "done_when":
            return done_when(project, body.get("step"), body.get("text"))
        if a == "place":
            return place(project, body.get("step"), body.get("band"), body.get("position") or 0)
        if a == "pace":
            return pace(project, body.get("step"), body.get("when"))
        if a == "withdraw":
            return withdraw(project, body.get("step"), body.get("seed"))
        if a == "restore":
            return restore(project, body.get("step"), body.get("navigation"), body.get("seed"))
        if a == "guide":
            return guide(project, body.get("step"), body.get("text"))
        if a == "not_now":
            return not_now(project, body.get("key"), body.get("fact"), body.get("text"))
        if a == "nudge_again":
            return nudge_again(project, body.get("key"))
        if a == "seat_new":
            return seat_new(project, body.get("ref"), body.get("name"), body.get("seat"))
        if a == "resume":
            return resume(project, body.get("note"), body.get("switched_to"))
        if a == "resume_done":
            return resume_done(project)
        if a == "if_then":
            return if_then(project, body.get("step"), body.get("text"))
        if a == "premortem":
            return premortem(project, body.get("step"), body.get("text"))
        if a == "premortem_skip":
            return premortem_skip(project, body.get("step"))
        if a == "premortem_ask":
            return premortem_ask(project, body.get("step"), body.get("reason"))
    except Exception as e:
        return _no("that did not go through: %s" % e)
    return _no("no such act")

def seat(project, step, seat, position=None):
    """Put a component on the desk: ACTIVE or ON DECK, at a position (the foot when none); one receipt naming the
    seat as it now is; the undo puts it back where it sat (its old seat and place, or its goal)."""
    s, refusal = _component(project, step)
    if refusal:
        return refusal
    seat = str(seat or "").strip().lower()
    if seat not in SEATS:
        return _no("a seat is active or deck")
    old_seat = s.get("seat") if s.get("seat") in SEATS else None
    old_pos = _seat_ids(project, old_seat).index(step) if old_seat and step in _seat_ids(project, old_seat) else None
    if old_seat == seat and position is None:
        return _no("%s is already %s" % (s.get("name"), "active" if seat == "active" else "on deck"))
    place = int(position) if position is not None else len(_seat_ids(project, seat, except_id=step))
    r = _cli(project, "roadmap-set", "--step", step, "--seat-in", seat, "--seat-order", str(place))
    if not r.get("ok"):
        return _no("the engine refused: %s" % r.get("error"))
    undo = {"act": "seat", "step": step, "seat": old_seat, "position": old_pos or 0} if old_seat else {"act": "home", "step": step}
    err = _place_seat(project, step, seat, place)
    if not err and old_seat and old_seat != seat:
        err = _renumber_seat(project, old_seat)
    if err:
        return _no("%s is %s, but the order could not close up: %s \u2014 undo puts it back" % (s.get("name"), "active" if seat == "active" else "on deck", err), undo=undo)
    g = _goal_of(project, s)
    where = ("%s (%s)" % (s.get("name"), g.get("name"))) if g else s.get("name")
    return _ok("%s is %s \u2014 %s" % (where, "active" if seat == "active" else "on deck", _seat_line(project, seat)), undo=undo)

def move_tier(project, step, tier, order=None):
    """Move an initiative to a tier: one step_set of its tier, then its place — the foot of that tier, or the
    order the undo carries (so a head of a tier comes back as its head, not at the bottom with a new number)."""
    s = _step(project, step)
    if s is None or _own_group(s) is None:
        return _no("no such goal")
    try:
        tier = int(tier)
    except Exception:
        return _no("a tier is 1, 2 or 3")
    if tier not in (1, 2, 3):
        return _no("a tier is 1, 2 or 3")
    old = s.get("tier")
    old_order = int(_own_group(s).get("order") or 0)
    if old == tier:
        return _no("%s is already in tier %d" % (s.get("name"), tier))
    r = _cli(project, "roadmap-set", "--step", step, "--tier", str(tier))
    if not r.get("ok"):
        return _no("the engine refused: %s" % r.get("error"))
    place = int(order) if order is not None else _foot(project, tier, except_id=step)
    r2 = _write_nav(project, _step(project, step), order=place)
    if not r2.get("ok"):
        return _no("%s moved to tier %d, but its place there was refused: %s — it keeps its old order number" % (s.get("name"), tier, r2.get("error")))
    return _ok("%s moved to tier %d (from %s), %s" % (s.get("name"), tier, ("tier %d" % old) if old else "no tier",
                                                      ("at its foot" if order is None else "back in its place")),
               undo={"act": "move_tier", "step": step, "tier": old, "order": old_order} if old else None)

def guide(project, step, text):
    """W2d (2026-09-30): his revision of a goal's guide from its place. The steward writes the guide on his word in the
    conversation; this is his own hand on the file - written whole with a dated History line, committed. No undo: the
    History line and the Campaign's commits keep every version."""
    s = _step(project, step)
    if not s or not _own_group(s):
        return _no("no such goal")
    from .steward_campaign import write_guide
    r = write_guide(project, step, text, who="John")
    if not r.get("ok"):
        return _no(str(r.get("error") or "the guide was not written"))
    return _ok("the guide of %s revised \u2014 %s" % (s.get("name"), r.get("note") or "written"), undo=None, updated=r.get("updated"))

def say_campaign(folder, text, dialogue=None, today=None, goal=None):
    """None when the words are not a Campaign verb (the steward takes them); else the act's answer. With ``goal``
    (an initiative id: the words were said inside that goal's place) the scoped forms are read first."""
    if goal:
        scoped = _scoped(folder, str(goal), text, today or date.today())
        if scoped is not None:
            return scoped
    bare = _bare_pace(folder, text, today or date.today())
    if bare is not None:
        return bare
    c = compile_utterance(text, dialogue)
    if c is None:
        return _refuse("the Campaign\u2019s grammar could not be read (the engine did not answer) \u2014 nothing was done", "campaign_compile")
    if not c.get("campaign"):
        return None
    try:
        return _apply(folder, c, today or date.today())
    except Exception as e:
        return _refuse("that did not go through: %s \u2014 look at the board before saying it again" % e, str(c.get("act") or "campaign_act"))

def is_cave_folder(folder):
    try:
        return Path(str(folder)).resolve() == (campaign_dir() / CAVE_EFFORT).resolve()
    except Exception:
        return False

def dismiss(campaign_dir, key, fact="", text=""):
    """His 'not now': a receipt that silences that nudge until its fact changes. Written whole, never raises."""
    key = str(key or "").strip()
    if not key or len(key) > 120 or "/" in key or "\\" in key:
        return {"ok": False, "error": "no such nudge"}
    d = read_dismissed(campaign_dir)
    d[key] = {"at": time.strftime("%Y-%m-%d %H:%M"), "fact": str(fact or "")[:200], "text": str(text or "")[:240]}
    try:
        p = _path(campaign_dir); p.parent.mkdir(parents=True, exist_ok=True)
        tmp = p.with_suffix(".json.tmp"); tmp.write_text(json.dumps(d, indent=1, ensure_ascii=False), encoding="utf-8"); os.replace(str(tmp), str(p))
    except OSError as e:
        return {"ok": False, "error": "the receipt could not be kept: %s" % e}
    return {"ok": True, "key": key}

def read_guide(campaign_dir, goal_id):
    """{exists, text, updated, history, rel}; a missing guide is exists False, never an error."""
    rel = guide_rel(goal_id)
    out = {"exists": False, "text": "", "updated": "", "history": [], "rel": rel or ""}
    if not rel:
        return out
    path = Path(campaign_dir) / rel
    try:
        text = path.read_text(encoding="utf-8")
        st = path.stat()
    except OSError:
        return out
    out.update(exists=True, text=text.replace("\r\n", "\n"), updated=time.strftime("%Y-%m-%d %H:%M", time.localtime(st.st_mtime)), history=_guide_history(text))
    return out

def _contract(self):
    if self.code_job:
        return CODER_CONTRACT
    if self.effort_on():
        return EFFORT_DUTY + CONTRACT + EFFORT_RULES
    return SMALL_DUTY + CONTRACT

def say(self, text, human=True, question_id=None, goal=None):
    text = (text or "").strip()
    if not text:
        return {"ok": False, "error": "empty"}
    if human:   # W1 of the two-lane plan (2026-10-05): the queue wait is measured from his message's arrival
        self._human_arrivals = (getattr(self, "_human_arrivals", None) or [])[-20:] + [time.time()]
    goal = str(goal or "").strip() or None      # W2 v2: said inside a goal's place — recorded with the tag, sent with the scope
    goal_name = ""
    if goal:
        try:
            from steward_cockpit import campaign_acts as _acts
            _g = _acts._step(self.dir, goal)
            goal_name = str((_g or {}).get("name") or "")
        except Exception:
            goal_name = ""
        if not goal_name:
            goal = None
    if human and not self.general and not self.code_job:
        # R2/R3 (2026-10-04): his words set the mode and stop a code job; the message still goes to the steward
        if _EFFORT_ON.search(text) or _EFFORT_OFF.search(text):
            on = bool(_EFFORT_ON.search(text))
            _update_state(self.skey(), {"effort_mode": on})
            self._emit({"t": "sys", "text": "effort rules on - the full plan discipline applies here" if on else "small mode - small changes stay small; real work goes to a code job"})
        if _STOP_CODER.match(text):
            try:
                from steward_cockpit import code_jobs as _cj
                from steward_cockpit import steward_routes as _sr
                r = _cj.stop(self.dir, engine_lookup=lambda wt: _sr.get_engine(wt, general=True, tid="1", create=False))
                self._emit({"t": "sys", "text": ("code job stopped; its work so far stays on branch " + r["branch"]) if r.get("ok") else ("no code job to stop: " + str(r.get("error")))})
            except Exception as e:
                self._emit({"t": "sys", "text": "the code job could not be stopped: %s" % e})
    answer_context = None
    if question_id:
        answer_context = next((q for q in self._question_contexts(self._attention()) if q["id"] == question_id), None)
        if not answer_context:
            return {"ok": False, "error": "This question changed or was resolved. Open the current question before answering."}
    if not self.alive():
        ok, why = self.wake()
        if not ok:
            from steward_cockpit import maintenance
            if human and maintenance.is_active():
                # Wave 1.6: accepted durably, delivered after activation.
                with self._lock:
                    if not self._record_conversation("john", text, goal=goal):
                        return {"ok": False, "error": "your message was not accepted because durable conversation storage failed"}
                    self.queue.append(_scoped_text(text, goal, goal_name))
                    if not self._persist_queue():
                        self.queue.pop()
                        return {"ok": False, "error": "could not durably queue your text"}
                    self._emit({"t": "john", "text": text})
                    self._emit({"t": "sys", "text": "queued - maintenance in progress; delivered when the steward resumes"})
                return {"ok": True, "queued": True, "maintenance": True}
            if human:
                # W2e (2026-09-30, John: "not delivered - your text is back in the box" after a restart): a wake that
                # failed (the provider deferred, the settings unreadable, the CLI gone) keeps his words durably; they
                # go on the next wake - never his to retype. A control that cannot be delivered is simply not sent.
                with self._lock:
                    if not self._record_conversation("john", text, goal=goal):
                        return {"ok": False, "error": "your message was not accepted because durable conversation storage failed"}
                    self.queue.append(_scoped_text(text, goal, goal_name))
                    if not self._persist_queue():
                        self.queue.pop()
                        return {"ok": False, "error": "could not durably queue your text"}
                    self._emit({"t": "john", "text": text})
                    self._emit({"t": "sys", "text": "the steward could not wake just now (" + str(why) + ") - your text is kept and goes when it wakes"})
                return {"ok": True, "queued": True, "kept": True}
            return {"ok": False, "error": why}

    # One ingress transaction: update the human/control state, append the
    # visible event, and either queue or write stdin under the same lock as
    # result-boundary arbitration. A displayed human turn therefore can
    # never be followed by an automatic nudge/drive write before it lands.
    wait = self._attention() if human else {}
    with self._lock:
        control = ""
        if human:
            if question_id and not any(q["id"] == question_id for q in self._question_contexts(wait)):
                return {"ok": False, "error": "Question is no longer current"}
            if not self._record_conversation("john", text, goal=goal):
                return {"ok": False, "error": "your message was not accepted because durable conversation storage failed"}
            # Only bare UI commands are controls. "go with option B" and
            # "hold on" are substantive words, not drive switches.
            low = text.lower().rstrip(".!").strip()
            if low == "go":
                self.drive = True
                self.auto_count = 0
                control = "go"
            elif low in ("pause", "stop", "hold"):
                self.drive = False
                control = "pause"
            self.last_say = time.time()
            self.john_msgs += 1
            self._human_asked = text.rstrip().endswith("?")
            self._answer_nudged = False
            self._decision_nudged = False
            if answer_context:
                entry = {"question":answer_context, "answer":text, "answered_at":time.time(),
                         "status":"response_recorded", "source_ref":"Cockpit conversation"}
                history = (getattr(self, "question_history", []) + [entry])[-100:]
                if not _update_state(self.skey(), {"question_history":history}):
                    return {"ok": False, "error": "Question response context could not be saved"}
                self.question_history = history
                if not (answer_context.get("authorization_scope") or {}).get("request_id"):
                    self._strip_clear_wait()    # a decision answered: the wait on John is over (C2)
                    try:
                        from . import horizon as _horizon
                        _horizon.refresh(self.dir, "answered")   # W3 (2026-09-28): the line follows the answer
                    except Exception:
                        pass

            if wait.get("managed_refinement"):
                # Conversation and drive controls never resolve a review.
                # Only a lifecycle operation can change its pending request.
                self.open_question = ""
                self.open_question_kind = ""
                if control and self._question_contexts(wait):
                    self._emit({"t": "john", "text": text})
                    return {"ok": True, "queued": False, "control_only": True}
            elif self.open_question:
                kind = (self.open_question_kind
                        or _question_kind(self.open_question))
                if control and kind != "drive_offer":
                    # Drive is an interface command, not an answer. Never
                    # put a bare approval-shaped token on model stdin.
                    self._emit({"t": "john", "text": text})
                    self._emit({"t": "sys", "text":
                                ("drive armed" if control == "go"
                                 else "drive paused")
                                + " - still waiting on: "
                                + self.open_question})
                    return {"ok": True, "queued": False,
                            "control_only": True}
                self.open_question = ""
                self.open_question_kind = ""
                _update_state(self.skey(), {
                    "open_question": "",
                    "open_question_kind": "",
                    "question_context": None,
                })
            if not control:
                self.question_context = None
                _update_state(self.skey(), {"question_context":None})

        self._emit({"t": "john" if human else "sys", "text": text})
        text = _scoped_text(text, goal, goal_name)      # the model is told which goal he is in; his shown words stay his own
        if answer_context:
            text += ("\n\n(answer context, not a new request) This response concerns only the saved question and "
                     "versions below. Recheck applicability before acting; this is not automatic acceptance.\n" +
                     json.dumps(answer_context, ensure_ascii=False))
        # (2026-09-05, John: "the plan does not get updated") while the
        # roadmap is behind the plan documents, his turn carries the drift
        # line on the model's stdin - his displayed words stay his own.
        if self.busy:
            # queued RAW: the drift line is computed when this is delivered
            # (a line computed now can be false by then — journal 0111)
            self.queue.append(text)
            if not self._persist_queue():
                self.queue.pop()
                self.broken = True
                self._emit({"t": "sys", "text":
                            "queue persistence failed - your text was "
                            "not accepted; please retry after storage "
                            "is healthy"})
                return {"ok": False,
                        "error": "could not durably queue your text"}
            if human and self._turn_origin != "human":
                # Wave 1.2: his words outrank a self-started turn (drive,
                # nudge, stand-up). The turn is ended, its outcome recorded
                # as uncertain, and his message goes next.
                self._emit({"t": "sys", "text": "your message arrived during a self-started turn - ending that turn; your message goes next"})
                self._interrupt_turn_locked("human message arrived during a self-started turn")
                ok, why = self._wake_locked(fresh=False, seed=None)
                if not ok:
                    self._emit({"t": "sys", "text": "steward could not resume after the interruption: " + str(why) + "; your message is queued"})
                return {"ok": True, "queued": bool(self.queue), "interrupted": True}
            # R1 (steward responsiveness, 2026-10-04): the receipt names what the steward is on and since
            # when, and carries "Take this now" (interrupt, then deliver his message at once)
            if human:
                self._emit({"t": "sys", "text": self._queued_receipt(), "take_now": True})
            else:
                self._emit({"t": "sys", "text": "queued - the steward is mid-turn; it will be delivered next"})
            return {"ok": True, "queued": True}
        from steward_cockpit import maintenance
        if human and maintenance.is_active():
            # Wave 1.6 (Grok R1 F3): an alive, idle steward behind the
            # barrier takes no new turn; his words wait durably.
            self.queue.append(text)
            if not self._persist_queue():
                self.queue.pop()
                return {"ok": False, "error": "could not durably queue your text"}
            self._emit({"t": "sys", "text": "queued - maintenance in progress; delivered when the steward resumes"})
            return {"ok": True, "queued": True, "maintenance": True}
        ok = self._send_locked(text + (self._plan_drift_suffix() if (human and not self.general and self.effort_on()) else ""),
                               origin="human" if human else "control")
    if not ok:
        return {"ok": False, "error": "delivery failed - your text was not sent"}
    return {"ok": True, "queued": False}

def _select_available_policy(self, settings, target, excluded=()):
    """Bounded prelaunch selection, exclusively among dashboard families."""
    import model_policy
    ladder = list(dict.fromkeys([target] + [settings[k] for k in ("coding_family", "review_family", "default_cli")]))
    if settings.get("provider_preferences", {}).get("family"):
        ladder = [target]  # An explicit account choice never borrows another subscription.
    failed = []
    for family in ladder:
        if family in excluded:
            continue
        try:
            if family not in ("claude", "chatgpt", "grok"):
                raise RuntimeError("native cockpit capability contract is not verified")
            if family == "grok" and not (HERE / "grok_turn_bridge.py").is_file():
                raise RuntimeError("native Grok cockpit adapter is unavailable")
            if self.provider_connection["family"] == family and (not self.provider_connection["native_default"] or self.provider_quality):
                import provider_setup as _provider_setup
                bound_settings = {**settings, "provider_preferences": {**settings["provider_preferences"],
                                 "quality": {family: self.provider_quality} if self.provider_quality else {}}}
                selection = _provider_setup.resolve_quality(family, bound_settings, self.provider_connection)
            else:
                selection = model_policy.resolve(family, settings=settings)
        except (ValueError, RuntimeError) as exc:
            failed.append(family)
            self._journal_routing(action="unavailable", family=family,
                                  message=family + " preflight unavailable: " + str(exc))
            continue
        if family != target:
            self._journal_routing(action="failover", requested=target, actual_family=family,
                                  model_served=None, cross_model=False,
                                  message=target + " -> " + family + "; selected-provider fallback, cross_model:false")
            self.policy_override = {"family": family, "revision": settings["settings_revision"],
                                    "reason": "visible_failover", "failed_families": list(excluded)}
        return family, selection
    self._journal_routing(action="halt", message="No capable selected cockpit provider remains")
    raise RuntimeError("No capable selected cockpit provider remains; check subscription health")

def record_status_ack(self, at=""):
    """The wakeup-delivery lesson, mechanized: the pane POSTs an ack AFTER
    it RENDERS a status, so delivery is a receipt, not a hope. The first
    ack ever flips channel_verified — the one-time 'this channel reaches
    John' acknowledgment; every ack updates the render-leg log."""
    try:
        now = time.strftime("%Y-%m-%dT%H:%M:%S")
        state = {"first": False}
        def _mut(d):
            state["first"] = not d.get("channel_verified")
            d["channel_verified"] = True
            if state["first"]:
                d["channel_verified_at"] = now
            d["last_render_ack_at"] = now
            d["last_acked_status_at"] = str(at or "")
            d["render_acks"] = int(d.get("render_acks", 0)) + 1
        self._delivery_patch(_mut)
        return {"ok": True, "channel_verified_first_time": state["first"]}
    except Exception as e:
        return {"ok": False, "error": f"{type(e).__name__}: {e}"}

def _retry_refinement_handoffs(self):
    """Drain one saved observation through the existing ledger, never under the stdin lock."""
    if not getattr(self, "_pending_refinement_handoffs", {}):
        return True
    if not self._refinement_retry_lock.acquire(blocking=False):
        return False
    try:
        with self._refinement_pending_lock:
            if not self._pending_refinement_handoffs:
                return True
            producer_id, payload = next(iter(self._pending_refinement_handoffs.items()))
            # A failed session-state write must not silently orphan an observation.
            if not _update_state(self.skey(), {
                    "pending_refinement_handoffs": self._pending_refinement_handoffs}):
                return False
        from steward_cockpit.producer_handoff import record_handoff
        try:
            receipt = record_handoff(self.dir, **payload)
        except Exception as exc:
            receipt = {"ok": False, "error": "handoff-recording-failed",
                       "detail": type(exc).__name__}
        with self._refinement_pending_lock:
            remaining = dict(self._pending_refinement_handoffs)
            if receipt.get("ok"):
                remaining.pop(producer_id, None)
            acknowledged = _update_state(self.skey(), {
                "pending_refinement_handoffs": remaining,
                "refinement_handoff": receipt})
            if acknowledged:
                self._pending_refinement_handoffs = remaining
        error = (receipt.get("error") if not receipt.get("ok") else
                 "handoff-receipt-persistence-failed" if not acknowledged else None)
        if error and error != self._refinement_handoff_error:
            self._emit({"t": "sys", "text": "Work completed, but its refinement handoff needs repair: " + str(error)})
        self._refinement_handoff_error = error
        return bool(receipt.get("ok") and acknowledged)
    finally:
        self._refinement_retry_lock.release()

def start(cdir, repo, brief, check="", engine_factory=None, steward=""):
    """Start a code job for the steward at ``cdir``: a worktree of ``repo`` and a coder engine given ``brief``.
    ``engine_factory(worktree) -> engine`` is the seam (steward_routes passes get_engine)."""
    brief = str(brief or "").strip()
    if not brief:
        return {"ok": False, "error": "a code job needs a brief"}
    root = _repo_root(repo or "")
    if root is None:
        return {"ok": False, "error": "not a git repository: %s" % repo}
    job_id = time.strftime("%Y%m%d-%H%M%S") + "-" + uuid.uuid4().hex[:6]
    branch = "steward-job-" + job_id
    wt = jobs_base() / job_id
    with _LOCK:      # the check, the worktree and the busy entry: one step, so two stewards never both start
        if _norm(root) in busy_repos():
            return {"ok": False, "error": "a code job is already running on %s; one writer at a time" % root}
        code, base, err = _git(root, "rev-parse", "HEAD")
        if code != 0:
            return {"ok": False, "error": "the repository has no commit to start from: %s" % err}
        code, _, err = _git(root, "worktree", "add", "-b", branch, str(wt), base, timeout=600)
        if code != 0:
            return {"ok": False, "error": "could not make the worktree: %s" % err[:300]}
        job = {"id": job_id, "repo": str(root), "branch": branch, "worktree": str(wt), "base": base, "brief": brief[:8000],
               "check": str(check or "")[:500], "status": "running", "started": time.strftime("%Y-%m-%d %H:%M:%S"),
               "steward_dir": str(cdir), "steward": steward}
        _write_job(cdir, job)
        b = _busy_read()
        b[_norm(root)] = {"job": job_id, "cdir": str(cdir)}
        _busy_write(b)
    # the coder's own folder record: one workbench terminal
    terms = Path(wt) / ".anchor" / "steward-terms.json"
    terms.parent.mkdir(parents=True, exist_ok=True)
    terms.write_text(json.dumps({"1": {"label": "code job " + job_id, "created": job["started"], "archived": False}}), encoding="utf-8")
    _exclude_local(wt)
    try:
        eng = engine_factory(str(wt)) if engine_factory else None
        if eng is None:
            raise RuntimeError("no engine slot for the coder")
        eng.code_job = {"cdir": str(cdir), "id": job_id, "repo": str(root)}
        eng.on_turn_done = lambda result: threading.Thread(target=finish, args=(cdir, job_id, result), name="code-job-" + job_id, daemon=True).start()
        ok, why = eng.wake(fresh=True, seed=coder_brief(job))
        if not ok:
            raise RuntimeError(why)
    except Exception as e:
        j = _transition(cdir, job_id, LIVE, status="failed", finished=time.strftime("%Y-%m-%d %H:%M:%S"), error="the coder could not start: %s" % e)
        _cleanup(j or job, keep_branch=False)
        return {"ok": False, "error": "the coder could not start: %s" % e, "job": job_id}
    return {"ok": True, "job": job_id, "branch": branch, "worktree": str(wt)}

def _finish(cdir, job_id, job, result):
    wt, repo = job["worktree"], job["repo"]
    summary = str((result or {}).get("text") or "")[-1500:]
    err = str((result or {}).get("error") or "")
    check_out, check_ok = "", None
    if job.get("check") and not err:
        try:
            r = subprocess.run(job["check"], cwd=wt, shell=True, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=CHECK_TIMEOUT_S)
            check_ok = r.returncode == 0
            check_out = ((r.stdout or "") + (r.stderr or ""))[-1200:]
        except Exception as e:
            check_ok, check_out = False, "the check did not run: %s" % e
    commit_err = ""
    files = []
    code, _, gerr = _git(wt, "add", "-A", timeout=600)
    if code != 0:
        commit_err = "git add failed: " + gerr[:250]
    if not commit_err:
        code, staged, gerr = _git(wt, "diff", "--cached", "--name-only", timeout=600)
        if code != 0:
            commit_err = "git diff failed: " + gerr[:250]
        elif staged:
            code, out, gerr = _git(wt, "commit", "-q", "-m", "Code job %s for the steward\n\n%s" % (job_id, job["brief"][:600]), timeout=600)
            if code != 0:
                commit_err = "git commit failed: " + (gerr or out)[:250]
    if not commit_err:
        # the change is what the branch holds beyond its base (the coder may have committed itself)
        code, names, gerr = _git(wt, "diff", "--name-only", job["base"], "HEAD", timeout=600)
        if code != 0:
            commit_err = "git diff failed: " + gerr[:250]
        else:
            files = [n for n in names.splitlines() if n.strip()]
    landed, land_note = False, ""
    if commit_err:
        land_note = "not landed: the commit failed (%s); the worktree is kept at %s" % (commit_err, wt)
    elif not files:
        land_note = "nothing changed"
    elif err:
        land_note = "not landed: the coder's turn ended in an error; the work waits on branch %s" % job["branch"]
    elif check_ok is False:
        land_note = "not landed: the check failed; the work waits on branch %s" % job["branch"]
    else:
        landed, land_note = land(job, files)
    landed_commit = ""
    if landed:
        c, out, _ = _git(repo, "rev-parse", "HEAD")
        landed_commit = out.strip() if c == 0 else ""
    done = _transition(cdir, job_id, ("finishing",), status="failed" if (err or commit_err) else "done",
                       finished=time.strftime("%Y-%m-%d %H:%M:%S"), summary=summary, error=err or commit_err,
                       check_ok=check_ok, check_output=check_out, files=files, landed=landed, land_note=land_note,
                       landed_commit=landed_commit)
    if done is None:
        return
    if not commit_err:
        _cleanup(done, keep_branch=not (landed or not files))
    _report(cdir, done)

def _land_under_lock(job, _gs):
    repo, wt = job["repo"], job["worktree"]
    code, head, err = _git(repo, "rev-parse", "HEAD")
    if code != 0:
        return False, "not landed: could not read %s HEAD (%s)" % (repo, err[:120])
    code, out, err = _git(wt, "merge", "--no-edit", head, timeout=600)       # the job's own worktree: safe
    if code != 0:
        _git(wt, "merge", "--abort")
        return False, "not landed: the work conflicts with newer changes in %s; it waits on branch %s" % (repo, job["branch"])
    if job.get("check"):
        try:
            r = subprocess.run(job["check"], cwd=wt, shell=True, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=CHECK_TIMEOUT_S)
            if r.returncode != 0:
                return False, "not landed: the check failed after bringing in newer changes; the work waits on branch %s" % job["branch"]
        except Exception as e:
            return False, "not landed: the check could not run after integration (%s)" % e
    code, src, _ = _git(wt, "rev-parse", "HEAD")
    code2, names, _ = _git(wt, "diff", "--name-only", head, src)
    if code != 0 or code2 != 0:
        return False, "not landed: could not read the integrated change"
    land_files = [n for n in names.splitlines() if n.strip()]
    if not land_files:
        return False, "nothing changed beyond what %s already has" % repo
    return _gs.land_locked(repo, src, land_files, "Code job %s for the steward\n\n%s" % (job["id"], job["brief"][:600]),
                           who="code job " + job["id"], expect_head=head)

def stop(cdir, job_id=None, engine_lookup=None):
    """His "stop": kill the running job (the newest when no id); its work so far stays on its branch."""
    jobs = [j for j in read_jobs(cdir).values() if j.get("status") in LIVE and (not job_id or j["id"] == job_id)]
    if not jobs:
        return {"ok": False, "error": "no code job is running"}
    job = sorted(jobs, key=lambda j: j["started"])[-1]
    if job.get("status") == "finishing":
        if time.time() - float(job.get("finishing_at") or 0) < CHECK_TIMEOUT_S + 900:
            return {"ok": False, "error": "the code job is already finishing; its result is on the way"}
        _transition(cdir, job["id"], ("finishing",), status="failed", finished=time.strftime("%Y-%m-%d %H:%M:%S"),
                    error="the job's finish never completed", land_note="released by stop; the work waits on branch %s" % job["branch"])
        return {"ok": True, "job": job["id"], "branch": job["branch"], "released": True}
    stopped = _transition(cdir, job["id"], ("running",), status="stopped", finished=time.strftime("%Y-%m-%d %H:%M:%S"),
                          land_note="stopped by John; nothing landed; the work so far stays on branch %s" % job["branch"])
    if stopped is None:
        return {"ok": False, "error": "the code job is already finishing; its result is on the way"}
    try:
        eng = engine_lookup(job["worktree"]) if engine_lookup else None
        if eng is not None:
            eng.on_turn_done = None
            eng.stop()
    except Exception:
        pass
    try:
        _git(job["worktree"], "add", "-A")
        _git(job["worktree"], "commit", "-q", "-m", "Code job %s stopped by John (unfinished)" % job["id"])
        _git(job["repo"], "worktree", "remove", "--force", job["worktree"], timeout=300)
    except Exception:
        pass
    return {"ok": True, "job": job["id"], "branch": job["branch"]}

def propose(folder: str, step_id: Optional[str] = None,
            skill: Optional[str] = None, depth: Optional[str] = None,
            who: str = "ecgberht-steward") -> dict:
    """Ask the engine to propose a commission for the step in hand.
    READ-ONLY — the reply carries requires_confirm and the hash John binds."""
    payload = {"project": str(folder), "who": who}
    if step_id:
        payload["step_id"] = step_id
    if skill:
        payload["skill"] = skill
    if depth:
        payload["depth"] = depth
    return run_bridge("propose-active", payload)

def record_handoff(campaign_dir, producer_kind, producer_id, source_ref,
                   context=None, outputs=None, inventory_complete=False, terminal="done"):
    """Record one idempotent handoff; retry a CAS conflict at most once."""
    context_warning = None
    if isinstance(context, dict) and context.get("ok") is False:
        # A dispatch-time read failure does not erase work that subsequently
        # completed. Preserve the diagnostic code, without presenting the
        # failure envelope as a snapshot or copying private diagnostic text.
        context_warning = _capture_warning(context)
        context = None
    if not isinstance(producer_kind, str) or producer_kind not in _PRODUCERS:
        return _failure("The producer kind must be job, conversation, or terminal.")
    if not isinstance(producer_id, str) or not producer_id.strip():
        return _failure("A stable producer ID is required.")
    if context is not None:
        if not isinstance(context, dict) or not isinstance(context.get("step_id"), str) or not context["step_id"]:
            return _failure("Dispatch context must identify its captured step.")
        if any(key not in context for key in _CONTEXT_FIELDS):
            return _failure("Dispatch context must retain its complete captured state.")
    if outputs is not None and not isinstance(outputs, list):
        return _failure("The output inventory must be an explicit list.")
    if type(inventory_complete) is not bool:
        return _failure("Inventory completeness must be explicit.")
    if not isinstance(terminal, str) or not terminal:
        return _failure("The producer terminal state is required.")

    result = _read(campaign_dir)
    if not result["ok"]:
        return _with_context_warning(result, context_warning)
    if not result["state"]["managed"]:
        return _with_context_warning({"ok": True, "skipped": True, "reason": "unmanaged"}, context_warning)
    identifier = _handoff_id(producer_kind, producer_id)
    existing = _existing(result, identifier)
    if existing is not None:
        return _with_context_warning(existing, context_warning)

    operation = {
        "action": "producer_handoff", "version": 1,
        "operation_id": identifier, "handoff_id": identifier,
        "expected_seq": result["sequence"],
        "step_id": context["step_id"] if context is not None else None,
        "producer_kind": producer_kind, "source_ref": deepcopy(source_ref),
        "dispatch_context": deepcopy(context),
        "outputs": deepcopy(outputs) if outputs is not None else [],
        "inventory_complete": inventory_complete, "terminal": terminal,
    }
    if context_warning is not None:
        operation["dispatch_error"] = context_warning["error"]
    outcome = refinement_client.update(campaign_dir, operation)
    conflict = _error_code(outcome)
    if not isinstance(outcome, dict) or outcome.get("ok") is not False or conflict not in {"sequence-conflict", "HANDOFF_EXISTS"}:
        return _with_context_warning(outcome, context_warning)

    # Re-read only to establish whether this exact handoff already committed
    # and obtain a new CAS sequence.  Never refresh its dispatch-time context.
    refreshed = _read(campaign_dir)
    if not refreshed["ok"]:
        return _with_context_warning(refreshed, context_warning)
    if not refreshed["state"]["managed"]:
        return _with_context_warning(outcome, context_warning)
    existing = _existing(refreshed, identifier)
    if existing is not None:
        return _with_context_warning(existing, context_warning)
    if conflict == "HANDOFF_EXISTS":
        return _with_context_warning(outcome, context_warning)
    retried = {**operation, "expected_seq": refreshed["sequence"]}
    return _with_context_warning(refinement_client.update(campaign_dir, retried), context_warning)

def append_turns(campaign_dir, turns, *, thread_id: str | None = None) -> int:
    """Validate a complete batch, then append it with one lock/read/replace.

    Additional JSON fields on each turn are preserved. Matching IDs are skipped
    using append_turn's role/text semantics. Any invalid item or conflicting ID
    rejects the whole batch, never leaving a partially imported conversation.
    """
    if not isinstance(turns, (list, tuple)):
        raise ConversationHistoryError("invalid_turn_batch")
    prepared = []
    batch_ids = {}
    for item in turns:
        if (
            not isinstance(item, dict)
            or item.get("role") not in ("john", "steward")
            or not isinstance(item.get("text"), str)
            or ("at" in item and not isinstance(item["at"], str))
            or ("turn_id" in item and (not isinstance(item["turn_id"], str) or not item["turn_id"]))
        ):
            raise ConversationHistoryError("invalid_turn_batch")
        try:
            # Detach caller-owned nested metadata and reject non-JSON values
            # before creating history directories or acquiring the file lock.
            encoded = json.dumps(item, ensure_ascii=False, allow_nan=False)
            encoded.encode("utf-8")
            turn = json.loads(encoded)
        except (TypeError, ValueError, UnicodeError, RecursionError) as exc:
            raise ConversationHistoryError("history_encoding_failed") from exc
        turn.setdefault("at", datetime.now(timezone.utc).isoformat())
        identity = turn.get("turn_id")
        if identity is not None:
            previous = batch_ids.get(identity)
            if previous is not None:
                if (previous["role"], previous["text"]) != (turn["role"], turn["text"]):
                    raise ConversationHistoryError("turn_id_conflict")
                continue
            batch_ids[identity] = turn
        prepared.append(turn)
    with _THREAD_LOCK:
        target, lock = _paths(campaign_dir, thread_id, create=bool(prepared))
        if not prepared:
            return 0
        with _process_lock(lock):
            _check_path(target, directory=False)
            document = _read(target)
            existing_ids = {turn["turn_id"]: turn for turn in document["turns"] if "turn_id" in turn}
            additions = []
            for turn in prepared:
                previous = existing_ids.get(turn.get("turn_id"))
                if previous is not None:
                    if (previous["role"], previous["text"]) != (turn["role"], turn["text"]):
                        raise ConversationHistoryError("turn_id_conflict")
                    continue
                additions.append(turn)
            if not additions:
                return 0
            document["turns"].extend(additions)
            try:
                payload = (json.dumps(document, ensure_ascii=False, allow_nan=False, indent=2) + "\n").encode("utf-8")
            except (ValueError, UnicodeError, RecursionError) as exc:
                raise ConversationHistoryError("history_encoding_failed") from exc
            if len(payload) > MAX_HISTORY_BYTES:
                raise ConversationHistoryError("history_size_limit")
            _replace(target, payload)
            return len(additions)

export function runCli(argv, io = {}) {
  const write = io.write ?? ((s) => process.stdout.write(s));
  const exit = io.exit ?? ((code) => process.exit(code));
  const result = main(argv);
  const exitCode = result && result.ok === true ? 0 : 1;
  write(`${JSON.stringify(result, null, 2)}\n`);
  exit(exitCode);
  return { result, exitCode };
}

export function main(argv) {
  const tokens = Array.isArray(argv) ? argv : [];

  if (!tokens.length) {
    return {
      ok: false,
      error: 'missing_verb',
      spelling: SPELLING,
      message: `${SPELLING} requires a closed verb. Pass one of the closed list.`,
      closed_verbs: [...CLOSED_VERBS],
    };
  }

  const parsed = parseRootsFromCliArgs(tokens);
  // Prefer first non-flag token as verb (supports `status --roots X` and `--roots X status`)
  let verb = null;
  let verbIndex = -1;
  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];
    if (t === '--roots' || t === '-R' || t === '--project' || t === '-p') {
      // skip flag and its value
      if (tokens[i + 1] && !tokens[i + 1].startsWith('-')) i++;
      continue;
    }
    if (t.startsWith('--roots=') || t.startsWith('--project=')) continue;
    // Other long options are not the verb
    if (t.startsWith('--') || t.startsWith('-')) {
      // value-taking flags already handled for roots/project; skip known pairs generically
      if (
        tokens[i + 1] &&
        !tokens[i + 1].startsWith('-') &&
        !t.includes('=')
      ) {
        // only skip value when this looks like a flag that takes one (heuristic: not boolean)
        const booleanFlags = new Set(['--dry-run', '--no-persist']);
        if (!booleanFlags.has(t)) i++;
      }
      continue;
    }
    verb = t;
    verbIndex = i;
    break;
  }

  if (!verb) {
    return {
      ok: false,
      error: 'missing_verb',
      spelling: SPELLING,
      message: `${SPELLING} requires a closed verb. Pass one of the closed list.`,
      closed_verbs: [...CLOSED_VERBS],
      cli_roots: parsed.roots,
      cli_project: parsed.project,
    };
  }

  const args = tokens.filter((_, i) => i !== verbIndex);
  return runVerb(verb, args);
}

export function routeUtterance(text, ctx = {}) {
  const trimmed = String(text ?? '').trim();
  if (!trimmed) return { lane: 'refuse', reason: 'empty_utterance' };

  if (wordCount(trimmed) <= ACT_MAX_WORDS) {
    // A SHORT utterance is command-shaped, so the destructive guard belongs here:
    // "delete all projects" must never compile to a verb.
    if (matchesDestructive(trimmed)) {
      return { lane: 'refuse', reason: 'destructive_free_form' };
    }
    const compiled = compileUtterance(trimmed, ctx);
    if (compiled.compiled) return { lane: 'act', compiled };
  } else {
    // A Campaign verb (High Seat W5) is command-shaped from its first word — "add a part to MBA Teaching: retool
    // homework 2 due Oct 27" runs past eight words — so it compiles at any length; compileUtterance runs the
    // destructive guard first, and the act writes nothing here: Anchor's Campaign writer applies it.
    const compiled = compileUtterance(trimmed, ctx);
    if (compiled.compiled && CAMPAIGN_ACT_IDS.includes(compiled.act)) return { lane: 'act', compiled };
  }

  // WHY THE DESTRUCTIVE GUARD DOES NOT RUN ON THE CONVERSE LANE (found in the
  // 2026-08-04 multi-turn smoke). John's real refinement was "...and DROP the separate
  // 'lock the decisions' stage, fold those decisions into the syllabus stage" —
  // DESTRUCTIVE_PATTERNS contains /\bdrop\b/, so the steward answered "Ecgberht will
  // not compile destructive free-form talk" to an ordinary editorial instruction. He
  // will say drop / remove / get rid of constantly while shaping a scaffolding.
  //
  // The guard's threat model is "free-form talk must never compile to a DESTRUCTIVE
  // VERB". On this lane nothing executes: the seat runs read-only (SEAT_ALLOWED_TOOLS),
  // the model has no write authority, and every proposal still needs a human
  // hash-bound confirm. So there is nothing here for the guard to protect, and applying
  // it anyway breaks the conversation it was meant to make safe.
  return { lane: 'converse' };
}

export function loadStewardContext(projectPath) {
  const surfaces = loadProjectSurfaces(projectPath);
  const loaded = loadProjectRoadmap(projectPath);
  const roadmap = loaded.exists && loaded.ok ? loaded.roadmap : null;
  const kickoff = roadmap ? projectKickoff(roadmap) : {
    ok: true,
    confirmed: null,
    open: null,
  };
  if (!kickoff.ok) {
    return {
      ok: false,
      code: CONVERSE_CODE.KICKOFF_CORRUPT,
      kickoff_check: kickoff,
    };
  }

  // Gate 5 / Wave 3: the store (<folder>/.ecgberht/kickoff/events.jsonl) is the lineage
  // of record for the kickoff conversation. A fresh session paints its latest OPEN
  // version from the store alone; the roadmap-ledger projection is the pre-Gate-5 lane
  // beside it. A store that cannot be read is reported by its own named row, never
  // guessed around.
  const store = readKickoffLineage(surfaces.project_path);
  if (!store.ok) {
    return { ok: false, code: store.code, store_check: store };
  }

  // loadProjectSurfaces returns the PARSED Face document ({ok, narrative, raw,
  // strip_fence}), so the narrative is read straight off it.
  const narrative = surfaces.face?.narrative ?? null;

  const projection = Array.isArray(roadmap?.roadmap_projection)
    ? roadmap.roadmap_projection : [];

  // THE STEP IN HAND, AND WHAT IT STILL NEEDS.
  //
  // This is what makes the steward walk alongside rather than hand over a document.
  // John: "I don't want to have to scaffold it all and go do the detail stuff later —
  // I could if I want to, but I don't have to." So detail is not demanded up front; it
  // is asked for one step at a time, when that step becomes the work.
  //
  // All three calls are PURE reads — no probe is written just because he opened the
  // chamber. The steward asks in its own voice, in the conversation; answers land as
  // typed elaboration events only when he actually answers.
  const active = findActiveStep(projection);
  let stepGaps = [];
  if (active && roadmap) {
    const detail = reconstructStepDetail(roadmap, active.step_id ?? active.id);
    if (detail && detail.ok !== false) {
      const predicate = evaluateCommissionability(detail);
      if (!predicate.ready) stepGaps = deriveTargetedQuestions(predicate, detail);
    }
  }

  // LIVE COMMISSIONED RUNS (2026-08-06, from John's day-one use). The seat could
  // not see run state, so it DISAVOWED a genuinely running Gandalf ("your Go
  // never reached the machinery") one turn after the machinery confirmed it.
  // The host's run records are the truth; read them so "is it running?" gets a
  // real answer. Read-only, best-effort, never authoritative for the roadmap.
  const commission_runs = readCommissionRuns(surfaces.project_path);

  // The step findings ledger — what runs and reflection have FED each step
  // (2026-08-07). Read for context; never authoritative for status.
  const findings = readStepFindings(surfaces.project_path);
  const step_findings = findings.ok ? findings.steps : {};

  // The DURABLE conversation — how the plan got where it is, in his words and the
  // steward's. Read for RECALL only; project state above still comes from the Face,
  // roadmap and Strip, and the ledger always wins (see conversation-log.mjs).
  const history = readConversationLog(surfaces.project_path, { limit: 20 });

  return {
    ok: true,
    project_path: surfaces.project_path,
    narrative,
    strip: surfaces.strip ?? null,
    roadmap,
    projection,
    active_step: active,
    step_gaps: stepGaps,
    confirmed_kickoff: store.confirmed ?? kickoff.confirmed,
    open_kickoff: store.open ?? kickoff.open,
    open_proposal: store.open ?? kickoff.open
      ?? (roadmap ? findOpenScaffoldProposal(roadmap) : null),
    kickoff_store: {
      state: store.state,
      next_version: store.next_version,
      prior_confirmed_hash: store.prior_confirmed_hash,
      proposal_count: store.proposal_count,
      receipt_count: store.receipt_count,
    },
    commission_runs,
    step_findings,
    history: history.ok ? history.turns : [],
    history_unreadable: history.ok ? false : true,
  };
}

export async function converse(projectPath, opts = {}) {
  // 0. MISSING and EMPTY are separate rows (Gate 5 / Wave 3): no utterance at all is not
  //    the same fact as an utterance with nothing in it, and neither is a seat failure.
  if (opts.utterance == null) {
    return kickoffTalkFailure(KICKOFF_TALK_CODE.MISSING, {
      error: 'utterance_missing',
      model_called: false,
    });
  }
  const utterance = String(opts.utterance);

  // 1. Control verbs never reach a model, and never spend.
  const routed = routeUtterance(utterance, { session: opts.session });
  if (routed.lane === 'refuse') {
    if (routed.reason === 'destructive_free_form') {
      return converseFailure(CONVERSE_CODE.DESTRUCTIVE, { error: routed.reason, routed: routed.lane });
    }
    return kickoffTalkFailure(KICKOFF_TALK_CODE.EMPTY, {
      error: routed.reason,
      routed: routed.lane,
      model_called: false,
    });
  }
  if (routed.lane === 'act') {
    return {
      ok: true,
      lane: 'act',
      compiled: routed.compiled,
      say: `Understood that as: ${routed.compiled.label ?? routed.compiled.act}.`,
      model_called: false,
      spent: false,
      ledger_write: false,
      dialogue_persisted: false,
    };
  }

  // 2. Rebuild durable context. A Face is a post-confirm projection, not a
  // brainstorming precondition; an empty project is valid kickoff context.
  const context = loadStewardContext(projectPath);
  if (!context.ok) {
    if (context.store_check) {
      // The store's own named row (unreadable / corrupt / bound) rides through unchanged.
      return {
        ...context.store_check,
        say: context.store_check.user_text,
        lane: 'converse',
        conversational: true,
        model_called: false,
        ledger_write: false,
        dialogue_persisted: false,
      };
    }
    return converseFailure(context.code ?? CONVERSE_CODE.KICKOFF_CORRUPT, {
      context_check: context,
    });
  }

  // 3. Seat must be safe BEFORE we send anything anywhere.
  const seats = opts.seats ?? resolveSeats({ prefs: opts.prefs, env: opts.env });
  if (!seats.ok || !isProductionSeatSafe(seats)) {
    return converseFailure(CONVERSE_CODE.SEAT_UNSAFE, {
      error: seats.error ?? 'seat_unsafe',
      seat_message: seats.message ?? null,
    });
  }

  // 4. BACKGROUND ALLOWANCE (John, 2026-08-05). Talking used to require confirming a
  //    budget before the steward would say anything: "I really don't want to do that.
  //    Might have like a background amount of effort and if it hits there then it can
  //    say hey we've hit this threshold do you want to carry on."
  //
  //    So an allowance opens ON ITS OWN the first time he talks. The law it replaces is
  //    "nothing spent without prior confirmation"; the law it keeps is the one that
  //    matters — the steward STOPS at the cap and asks, and cannot go past it without
  //    him saying so. Reaching the cap is a checkpoint (see BUDGET_REACHED below).
  let envState = readEnvelopeState(projectPath, {});
  if ((!envState.ok || !envState.live) && envState.code !== ENVELOPE_CODE.EXHAUSTED) {
    const opened = opts.openAllowance
      ? opts.openAllowance(projectPath)
      : { ok: false, skipped: 'no_opener_injected' };
    if (opened.ok) envState = readEnvelopeState(projectPath, {});
  }
  // THE SILENT BOOTSTRAP (Gate 5 / Wave 3). A new effort has no Face, no envelope, no
  // budget - and none of them is a precondition for brainstorming. Nothing is prompted
  // and nothing is written here: the Face is created ON confirmation and the envelope is
  // materialized INSIDE the confirmation receipt (Wave 2); until then the turn's spend
  // rides the result. An envelope that EXISTS keeps its own law below (debit; stop at
  // the cap and ask).
  const bootstrap = settleKickoffBootstrap({ face: context.narrative, envelope_state: envState });
  if ((!envState.ok || !envState.live) && !bootstrap.spend_deferred) {
    // A REACHED CAP IS A CHECKPOINT, NOT A WALL (John, 2026-08-04). Say what has
    // actually been spent and offer to carry on, rather than a bare refusal — the
    // decision to go past it is his, and it stays a human confirmation.
    if (envState.code === ENVELOPE_CODE.EXHAUSTED) {
      // readEnvelopeState nests the numbers under `balance` — reading them off the
      // top level silently yields undefined, and the checkpoint would have told John
      // "$0.00 of $0.00 spent", which is worse than no number at all.
      const bal = envState.balance ?? envState;
      const spent = Number(bal.spent_usd) || 0;
      const cap = bal.max_spend_usd;
      const onSpend = bal.bound !== 'compiles';
      return converseFailure(CONVERSE_CODE.BUDGET_REACHED, {
        code: CONVERSE_CODE.BUDGET_REACHED,
        status_code: CONVERSE_CODE.BUDGET_REACHED,
        bound: bal.bound ?? 'spend',
        spent_usd: spent,
        max_spend_usd: cap ?? null,
        envelope: envState,
        can_raise: onSpend,
        say: onSpend
          ? `We've reached the session budget — ${formatSpend(spent)} of `
            + `${formatSpend(cap ?? 0)} spent. I've stopped rather than keep `
            + 'spending. Tell me to carry on and I will, or raise the cap and we keep going.'
          : 'We\'ve reached this session\'s turn limit. Confirm a fresh budget and we carry on.',
      });
    }
    const code =
      envState.code === ENVELOPE_CODE.EXPIRED ? ENVELOPE_CODE.EXPIRED
      : CONVERSE_CODE.NO_ENVELOPE;
    return converseFailure(CONVERSE_CODE.NO_ENVELOPE, {
      code,
      status_code: code,
      envelope: envState,
    });
  }

  // 5. The seat call itself — injected, because engine/ may not spawn.
  //    The E1 bound payload (opts.e1, computed by the Anchor owner and
  //    injected at the bridge boundary) rides into the prompt's conditional
  //    ANSWER LAW block and into the turn-completion hook below.
  const prompt = buildStewardPrompt(context, utterance, { turns: opts.turns, e1: opts.e1 });
  if (typeof opts.seatCall !== 'function') {
    return converseFailure(CONVERSE_CODE.SEAT_UNREACHABLE, { error: 'no_seat_call_injected' });
  }

  // AFFORDABILITY, not just liveness. `live` only means "not yet over the cap" — an
  // envelope with a few cents left is live while the NEXT debit would be refused. Left
  // as-is the steward would spend a real model call and only then discover it could not
  // record the spend: money out, ledger silent. Stop at the checkpoint BEFORE the call.
  const balance = envState.balance ?? {};
  const remaining = balance.remaining_usd;
  if (remaining != null && Number.isFinite(Number(remaining))) {
    const estimate = Number(priceCompile(prompt, { seat: 'compile' }).cost_usd) || 0;
    if (estimate > Number(remaining)) {
      const spent = Number(balance.spent_usd) || 0;
      const cap = Number(balance.max_spend_usd) || 0;
      return converseFailure(CONVERSE_CODE.BUDGET_REACHED, {
        code: CONVERSE_CODE.BUDGET_REACHED,
        status_code: CONVERSE_CODE.BUDGET_REACHED,
        bound: 'spend',
        spent_usd: spent,
        max_spend_usd: cap,
        estimated_next_usd: estimate,
        can_raise: true,
        say:
          `This next turn would take us past the session budget — ${formatSpend(spent)} of `
          + `${formatSpend(cap)} spent already. I've stopped rather than run it. `
          + 'Raise the cap and I will carry straight on.',
      });
    }
  }

  const callSeat = async (text, role) => {
    try {
      return await opts.seatCall(text, {
        seat_family: seats.coding_family,
        driver: seats.coding_driver,
        role,
        // Only the planning turn is granted read-only project access.
        project_path: context.project_path,
      });
    } catch (e) {
      return { ok: false, reason: 'seat_call_threw', detail: String(e?.message ?? e) };
    }
  };

  // TALK FIRST, ALWAYS. The conversational tier holds the exchange and cannot write a
  // scaffolding — so the steward can never open by dumping a finished plan on him.
  let seatResult = await callSeat(prompt, SEAT_ROLE.CONVERSATIONAL);
  if (!seatResult || seatResult.ok !== true || !String(seatResult.text ?? '').trim()) {
    return converseFailure(CONVERSE_CODE.SEAT_UNREACHABLE, {
      error: 'seat_call_failed',
      reason: seatResult?.reason ?? 'no_reply',
      detail: seatResult?.detail,
    });
  }

  // 6. Parse strictly. An unreadable reply is reported, never salvaged.
  let parsed = parseStewardReply(seatResult.text);
  if (!parsed.ok) return { ...parsed, seat_reached: true };

  // PLAN SECOND, RARELY. Only when the conversation earned it does the FRONTIER tier
  // run — the slow, deep, expensive turn — and only that turn may frame a scaffolding.
  // A compact provisional proposal can be explicitly requested. The number of
  // exchanges never overrides adaptive discovery or the retained answers.
  const turnNumber = kickoffTurnNumber(opts.turns);
  const thinTurn = kickoffNeedsThinProposal({
    explicit_thin_proposal: opts.thin_proposal === true,
    turn_number: turnNumber,
    open_proposal: context.open_proposal,
    confirmed_kickoff: context.confirmed_kickoff,
    step_count: context.projection.length,
  });
  const planForced = thinTurn && parsed.reply.wants_plan !== true && !parsed.reply.proposal;
  let planUsage = null;
  if (parsed.reply.wants_plan === true || planForced) {
    const planPrompt = buildStewardPrompt(context, utterance, {
      turns: opts.turns,
      planning: true,
      plan_brief: parsed.reply.plan_brief,
      e1: opts.e1,
      thin_turn: thinTurn ? turnNumber : null,
    });
    const planResult = await callSeat(planPrompt, SEAT_ROLE.FRONTIER);
    if (planResult?.ok === true && String(planResult.text ?? '').trim()) {
      const planParsed = parseStewardReply(planResult.text);
      if (planParsed.ok && planParsed.reply.proposal) {
        // Keep the talking turn's voice; take the frontier turn's plan.
        // E1: the talking turn's answer-references survive the merge — a
        // question the first turn answered must not become unanswered
        // because the frontier turn framed a plan.
        const talkRefs = Array.isArray(parsed.reply.answer_references)
          ? parsed.reply.answer_references : [];
        const planRefs = Array.isArray(planParsed.reply.answer_references)
          ? planParsed.reply.answer_references : [];
        parsed = {
          ok: true,
          reply: {
            ...planParsed.reply,
            asks: parsed.reply.asks,
            gathering: false,
            answer_references: planRefs.length ? planRefs : talkRefs,
          },
        };
        planUsage = planResult.meta ?? null;
      }
    }
    // A failed planning turn is NOT a failed turn: he still gets the conversation, and
    // the steward says plainly that the framing did not come back rather than inventing
    // one. Falling through leaves `parsed` as the talking reply.
  }

  const meta = sanitizeSeatMeta({
    ...(seatResult.meta ?? {}),
    // A planning turn's tokens are the bulk of the spend — count both, or the debit
    // under-reports what was actually used.
    tokens: (Number(seatResult.meta?.tokens) || 0) + (Number(planUsage?.tokens) || 0),
    // Real dollars, both turns. The planning turn is the expensive one.
    cost_usd: (Number(seatResult.meta?.cost_usd) || 0) + (Number(planUsage?.cost_usd) || 0),
    seat_family: seats.coding_family,
    driver: seats.coding_driver,
  });
  // ACT on the check rather than merely computing it. An unread `ok` is a guard that
  // looks like protection and provides none — the exact shape this project has shipped
  // three times. If a vendor product model id reached the whitelist anyway, drop the
  // identity fields so nothing durable can carry one, and say so out loud.
  if (!meta.ok) {
    meta.usage.seat_family = null;
    meta.usage.driver = null;
    meta.usage.scrubbed_product_model_ids = meta.product_model_ids.length;
  }
  const reply = parsed.reply;

  // THE QUESTION CAP (Gate 5 / Wave 3): at most one natural question per turn, the North
  // Star's letter. The seat may write more; one is delivered and the rest are reported held.
  const capped = capKickoffQuestions(reply.asks);
  reply.asks = capped.asks;
  const questionsHeld = capped.held.length;

  // ONE debit seam for the closes below. With no envelope at all (a new effort) the spend
  // is DEFERRED - it rides the result and is materialized inside the confirmation receipt
  // - never silently dropped and never prompted for.
  const debitTurn = (suffix) => {
    if (bootstrap.spend_deferred) {
      return {
        ok: true,
        debited: false,
        deferred: true,
        deferred_to: bootstrap.envelope_materialized_in,
        tokens: meta.usage.tokens,
        cost_usd: meta.usage.cost_usd,
      };
    }
    return debitSessionEnvelope(projectPath, {
      kind: 'compile',
      text: prompt,
      tokens: meta.usage.tokens || undefined,
      cost_usd: meta.usage.cost_usd,
      auth: opts.auth,
      client_event_id: opts.client_event_id ? `${opts.client_event_id}-${suffix}` : undefined,
    });
  };
  const debitView = (debit) => (debit.deferred
    ? debit
    : debit.ok ? { debited: true, shown: debit.shown } : { debited: false, ...debit });

  // ── THE E1 TURN-COMPLETION HOOK (steward-e1 W2 — the W8 row) ─────────────
  // The turn attempts to close HERE. Under a RATIFIED bound, an open
  // question id with no typed answer-reference structurally blocks the
  // close with a named finding; an unratified/absent bound fails CLOSED by
  // name on the verdict (never a silent clean pass) without blocking. The
  // seat call already happened, so the spend is debited honestly either way
  // — a blocked turn never hides money that left.
  const turnClose = enforceTurnCompletion(reply, opts.e1 ?? null);
  if (turnClose.decision === E1_DECISION.BLOCK) {
    const debit = debitTurn('blocked');
    return {
      ok: true,
      lane: 'converse',
      turn_blocked: true,
      blocked: {
        finding: turnClose.finding,
        unanswered: turnClose.unanswered,
        // Nothing is lost: the reply is HELD, not delivered as a closed
        // turn — the drawn refusal state (V5 AG-BLOCKED-TURN) is what John
        // sees, so the cure never looks like "are you working".
        held_say: reply.say,
        message: 'The engine refused to close this turn: a direct question '
          + 'from John still lacks a typed answer-reference.',
      },
      turn_close: turnClose,
      say: 'The engine refused to close this turn: a direct question from '
        + 'John still lacks a typed answer-reference.',
      model_called: true,
      seat: { family: seats.coding_family, driver: seats.coding_driver },
      usage: meta.usage,
      debit: debitView(debit),
      steps_written: false,
      ledger_write: false,
      dialogue_persisted: false,
    };
  }

  // THE AMBIGUOUS ROW (Gate 5 / Wave 3): the thin turn came and went and the seat still
  // has no bundle. Named, with NO question attached (never a third question); the spend
  // is accounted honestly; nothing is written and the exchange is not recorded as a close.
  if (thinTurn && !reply.proposal) {
    const debit = debitTurn('ambiguous');
    return kickoffTalkFailure(KICKOFF_TALK_CODE.AMBIGUOUS, {
      error: 'no_bundle_by_thin_turn',
      turn: turnNumber,
      turn_number: turnNumber,
      plan_forced: planForced,
      held_say: reply.say,
      questions_held: questionsHeld + reply.asks.length,
      gathering: true,
      model_called: true,
      seat: { family: seats.coding_family, driver: seats.coding_driver },
      usage: meta.usage,
      debit: debitView(debit),
      turn_close: turnClose,
      steps_written: false,
      bootstrap,
    });
  }

  // Record the exchange. Durable, append-only, and NEVER authoritative: this is how
  // John reads back why the plan changed, not where the plan currently stands.
  const recordTurns = (proposalHash, itemCount = 0, proposalKind = 'scaffold') => {
    const appended = appendConversationTurns(
      projectPath,
      [{ role: 'john', text: utterance }, { role: 'steward', text: reply.say }],
      {
        proposal_hash: proposalHash ?? null,
        kind: proposalHash ? `${proposalKind}_proposed` : 'conversation',
        at: opts.at,
      },
    );
    // Portfolio memory: WHAT THE STEWARD DID, never what the project is. Best-effort —
    // the steward's own bookkeeping must not break a turn John cares about.
    noteStewardEffort({
      kind: proposalHash ? `${proposalKind}_proposed` : 'conversation',
      project_path: projectPath,
      project_id: opts.project_id ?? context.strip?.project_id ?? null,
      at: opts.at,
      summary: proposalHash
        ? proposalKind === 'kickoff'
          ? `Proposed kickoff synthesis v${reply.proposal?.version ?? 'next'} with ${itemCount} plan entries`
          : `Proposed a ${itemCount}-stage scaffolding`
        : 'Talked through the project; no proposal yet',
    });
    if (reply.asks?.length) {
      noteStewardEffort({
        kind: 'question_raised',
        project_path: projectPath,
        project_id: opts.project_id ?? context.strip?.project_id ?? null,
        at: opts.at,
        summary: reply.asks[0],
      });
    }
    return appended;
  };

  // STEWARD FEEDBACK LANDS FOR REAL. The seat used to SAY "journaled" with no
  // hands (fabricated act, caught live 2026-08-06); now the reply's typed
  // journal entries are written durably here, and only this makes it true.
  let journaled = null;
  if (Array.isArray(reply.journal) && reply.journal.length) {
    const fed = appendStewardFeedback(projectPath, reply.journal, { at: opts.at });
    journaled = fed.ok
      ? { entries: fed.appended }
      : { entries: 0, error: fed.error };
  }

  // DETAIL ACCRUES BY TALKING. When he answered something the step in hand was missing,
  // it lands as a typed elaboration_answer on the spine — so the plan fills in as the
  // conversation goes, and he never has to sit down and scaffold it all up front.
  let elaborated = null;
  if (reply.answers && context.active_step && Object.keys(reply.answers).length) {
    const rec = recordElaborationAnswers(projectPath, {
      step_id: context.active_step.step_id ?? context.active_step.id,
      answers: reply.answers,
      who: opts.who ?? 'john',
      at: opts.at,
    });
    elaborated = rec.ok
      ? { recorded: Object.keys(reply.answers), step_id: rec.step_id ?? null }
      : { recorded: [], error: rec.error ?? rec.code };
  }

  // 7. No proposal yet — still gathering. Debit the call that was actually made.
  if (!reply.proposal) {
    const logged = recordTurns(null);
    const debit = debitTurn('turn');
    return {
      ok: true,
      lane: 'converse',
      say: reply.say,
      asks: reply.asks,
      gathering: true,
      proposal: null,
      turn_number: turnNumber,
      questions_held: questionsHeld,
      plan_forced: planForced,
      bootstrap,
      // E1 (steward-e1 W2): every converse close carries its turn-close
      // verdict — an unenforceable bound rides BY NAME, never silently open.
      turn_close: turnClose,
      model_called: true,
      seat: { family: seats.coding_family, driver: seats.coding_driver },
      usage: meta.usage,
      debit: debitView(debit),
      // Said explicitly rather than left undefined: a talking turn writes no steps, and
      // a caller checking `steps_written === false` deserves a true answer, not absence.
      steps_written: false,
      elaborated,
      journaled,
      // The chamber shows the commission card on this signal — the model
      // routes "start Gandalf" here instead of pretending work began.
      wants_commission: reply.wants_commission === true,
      commission_skill: reply.commission_skill ?? null,
      commission_directive: reply.commission_directive ?? null,
      // Spoken project management from the High Seat: the host renders the
      // confirm card; nothing is created until John clicks it.
      project_create: reply.project_create ?? null,
      ledger_write: false,
      // The transcript IS now kept (durable, non-authoritative). Say so honestly
      // rather than leaving a stale `false` that misdescribes what happened.
      dialogue_persisted: logged.ok === true,
      conversation_log: logged.ok
        ? { appended: logged.appended, total: logged.total }
        : { appended: 0, error: logged.error ?? logged.code },
    };
  }

  // 8. A proposal. New kickoff synthesis uses its own strict lineage; legacy
  // scaffolding remains available for recorded replies and established callers.
  const kickoffProposal = reply.proposal.kind === 'kickoff';
  let proposed;
  let legacyRoadmap = null;
  if (kickoffProposal) {
    const debit = debitTurn('kickoff-debit');
    if (!debit.ok) {
      return {
        ...debit,
        lane: 'converse',
        say: reply.say,
        asks: reply.asks,
        model_called: true,
        conversational: true,
      };
    }
    // THE STORE is the lineage of record (Gate 5 / Wave 2's one store): the WHOLE bundle,
    // v1 on an empty lineage, superseding at the same version before a confirmation,
    // v(n+1) after one. The host asserts which seat authored it; nothing else is written.
    const host = {
      seat_family: meta.usage.seat_family,
      driver: meta.usage.driver,
      source_turn_id: opts.client_event_id ?? null,
      client_event_id: opts.client_event_id
        ? `${opts.client_event_id}-kickoff-propose` : undefined,
      at: opts.at,
    };
    proposed = openKickoffBundle(projectPath, {
      bundle: reply.proposal,
      ...host,
      timeoutMs: opts.timeoutMs,
    });
    if (proposed.ok && usesLegacyRoadmapLane(context)) {
      // THE LEGACY LANE: a stood-up campaign (a Face on disk) keeps the pre-Gate-5
      // roadmap-ledger kickoff path beside the store - the WH4 lane's interaction,
      // unchanged. Same bundle, same seat lineage, same source turn: the same hash on an
      // agreeing lineage. A NEW effort never reaches this branch and writes only the store.
      const mirrored = proposeKickoff(projectPath, {
        proposal: reply.proposal,
        project_id: opts.project_id ?? context.strip?.project_id ?? null,
        ...host,
      });
      legacyRoadmap = mirrored.ok
        ? {
          written: mirrored.event != null,
          proposal_hash: mirrored.proposal_hash,
          diverged: mirrored.proposal_hash !== proposed.proposal_hash,
        }
        : { written: false, code: mirrored.code, error: mirrored.error };
    }
    if (proposed.ok) {
      proposed.debit = debit.deferred
        ? debit
        : {
          ok: true,
          debited: true,
          shown: debit.shown,
          cost_usd: debit.shown?.cost_usd ?? debit.pricing?.cost_usd,
          envelope_id: debit.envelope_id ?? debit.envelope?.envelope_id,
          pricing: debit.pricing,
        };
    }
  } else {
    proposed = proposeScaffolding(projectPath, {
      goal: reply.proposal.goal,
      stages: reply.proposal.stages.map((s) => ({
        name: s.name,
        done_when: s.done_when,
        oranges: s.oranges,
        ...(s.step_type ? { step_type: s.step_type } : {}),
      })),
      tokens: meta.usage.tokens || undefined,
      cost_usd: meta.usage.cost_usd,
      auth: opts.auth,
      client_event_id: opts.client_event_id ? `${opts.client_event_id}-propose` : undefined,
      at: opts.at,
    });
  }

  if (!proposed.ok) {
    return {
      ...proposed,
      lane: 'converse',
      say: reply.say,
      asks: reply.asks,
      model_called: true,
      conversational: true,
    };
  }

  // Tagged with the proposal hash, so the reasoning can be read alongside the exact
  // proposal version it produced — the "how did we get here" John asked for.
  const itemCount = kickoffProposal
    ? proposed.proposal.plan_entries.length
    : proposed.proposal.steps.length;
  const logged = recordTurns(
    proposed.proposal_hash,
    itemCount,
    kickoffProposal ? 'kickoff' : 'scaffold',
  );

  return {
    ok: true,
    lane: 'converse',
    say: reply.say,
    asks: reply.asks,
    gathering: false,
    // E1 (steward-e1 W2): the proposal close carries its verdict too.
    turn_close: turnClose,
    conversation_log: logged.ok
      ? { appended: logged.appended, total: logged.total }
      : { appended: 0, error: logged.error ?? logged.code },
    proposal: proposed.proposal,
    proposal_hash: proposed.proposal_hash,
    proposal_id: proposed.proposal_id,
    proposal_kind: reply.proposal.kind,
    ...(kickoffProposal
      ? {
        plan_entry_count: proposed.proposal.plan_entries.length,
        // What the chamber shows and sends back: the prose John reads and BOTH hashes the
        // confirmation binds. State is the store's; the roadmap mirror is named beside it.
        rendered_prose: proposed.rendered_prose,
        rendered_prose_hash: proposed.rendered_prose_hash,
        version: proposed.version,
        prior_confirmed_hash: proposed.prior_confirmed_hash ?? null,
        supersedes: proposed.supersedes ?? null,
        kickoff_state: proposed.state,
        kickoff_phase: proposed.phase,
        legacy_roadmap: legacyRoadmap,
        turn_number: turnNumber,
        questions_held: questionsHeld,
        plan_forced: planForced,
        bootstrap,
      }
      : {
        foresight: reply.proposal.foresight,
        step_count: proposed.proposal.steps.length,
      }),
    model_called: true,
    seat: { family: seats.coding_family, driver: seats.coding_driver },
    usage: meta.usage,
    debit: proposed.debit,
    steps_written: false,
    elaborated,
    journaled,
    ledger_write: proposed.event != null,
    authoritative: false,
    applied: false,
    dialogue_persisted: logged.ok === true,
    confirm_hint: kickoffProposal
      ? 'This is a preview, not project truth — confirm this exact version to apply it.'
      : 'Nothing is written yet — confirm and these become the campaign roadmap.',
  };
}

export function suggestDepthFromStrip(stripOrSignals, opts = {}) {
  const signals = extractDispatchSignals(stripOrSignals);
  const result = lookupDispatch(signals, opts);
  const uncertainty_flags = [...signals.uncertainty_flags];
  if (
    result.flags.capacity_unknown &&
    !uncertainty_flags.includes('capacity_unknown')
  ) {
    uncertainty_flags.push('capacity_unknown');
  }
  if (result.flags.lite_bias && !uncertainty_flags.includes('LITE_bias')) {
    uncertainty_flags.push('LITE_bias');
  }

  return {
    ...result,
    signals,
    uncertainty_flags,
    capacity: signals.capacity,
  };
}

export function lookupDispatch(dims, opts = {}) {
  const table = opts.table ?? loadDispatchTable(opts);
  const d = {
    phase: normDim(dims.phase, 'any'),
    uncertainty: normDim(dims.uncertainty, 'low'),
    human_wait: normDim(dims.human_wait, 'none'),
    cost: normDim(dims.cost, 'low'),
  };

  const matches = (table.cells || []).filter((c) => cellMatches(c, d));
  matches.sort((a, b) => cellSpecificity(b) - cellSpecificity(a));

  let cell = matches[0] ?? null;
  let outcome = cell ? cell.outcome : DEFAULT_BIAS;
  let why = cell?.why ?? (cell ? `table cell → ${outcome}` : 'default LITE bias (no matching cell)');
  let matched = Boolean(cell);
  const flags = {
    lite_bias: true,
    capacity_unknown: dims.capacity === 'unknown' || dims.flags?.capacity_unknown === true,
    silent_full_green: false,
    unknown_data_shape: d.cost === 'unknown_shape' || dims.flags?.unknown_data_shape === true,
    human_wait_blocked: d.human_wait === 'blocked',
    demoted_from_full: false,
    table_default: !matched,
  };

  // capacity=unknown: never silent FULL green — demote FULL → LITE with flag
  if (flags.capacity_unknown && outcome === 'FULL') {
    flags.demoted_from_full = true;
    why = `${why}; capacity=unknown demotes FULL → LITE (never silent FULL green)`;
    outcome = 'LITE';
  }

  // LITE bias flag on LITE outcomes, capacity-unknown, or unmatched default
  flags.lite_bias =
    outcome === 'LITE' || flags.capacity_unknown || flags.table_default;

  // Explicit: never report silent FULL green
  flags.silent_full_green = false;

  const tool_depth_why = buildToolDepthWhy({ outcome, why, dims: d, flags, cell });

  return {
    ok: true,
    table_ready: true,
    outcome,
    cell: cell
      ? {
          phase: cell.phase,
          uncertainty: cell.uncertainty,
          human_wait: cell.human_wait,
          cost: cell.cost,
          outcome: cell.outcome,
          why: cell.why,
        }
      : {
          phase: d.phase,
          uncertainty: d.uncertainty,
          human_wait: d.human_wait,
          cost: d.cost,
          outcome: DEFAULT_BIAS,
          why: 'default LITE bias',
          synthetic: true,
        },
    dimensions: d,
    flags,
    why,
    tool_depth_why,
    bias: DEFAULT_BIAS,
    matched,
  };
}

export function applyDepthOverride(fromOutcome, toOutcome, reason = {}) {
  const from = normalizeOutcome(fromOutcome);
  const to = normalizeOutcome(toOutcome);
  const issues = [];
  if (!from) issues.push('override.from required (valid outcome)');
  if (!to) issues.push('override.to required (valid outcome)');
  for (const key of ['who', 'when', 'why']) {
    if (reason[key] == null || reason[key] === '') {
      issues.push(`override.${key} required`);
    }
  }
  if (issues.length) {
    return {
      ok: false,
      error: 'override_receipt_required',
      message: `Human override requires structured receipt reason (who/when/why/from→to): ${issues.join('; ')}`,
      issues,
    };
  }
  return {
    ok: true,
    outcome: to,
    override: {
      who: reason.who,
      when: reason.when,
      why: reason.why,
      from,
      to,
    },
    tool_depth_why: `human override ${from}→${to}: ${reason.why}`,
  };
}

export function resolveSeats(opts = {}) {
  const prefs = loadAnchorPrefs(opts);
  const coding_driver = familyToSubscriptionDriver(prefs.coding_family);
  const review_driver = familyToSubscriptionDriver(prefs.review_family);

  const seat = {
    coding_family: prefs.coding_family,
    review_family: prefs.review_family,
    default_cli: prefs.default_cli,
    coding_driver,
    review_driver,
    /** Honest stamp: false when same-family; true when families differ. */
    cross_model: prefs.coding_family !== prefs.review_family,
    prefs_source: prefs.source,
    subscription_only: true,
    /** Production seats never use raw xAI HTTP + API key. */
    xai_http_seat: false,
    xai_api_key_path: false,
    product_model_ids: [],
    drivers: {
      coding: coding_driver,
      review: review_driver,
    },
  };

  // Fail closed if a driver is missing or not a subscription CLI
  const drivers = [coding_driver, review_driver];
  for (const d of drivers) {
    if (!d || !PRODUCTION_SEAT_DRIVERS.includes(d)) {
      seat.ok = false;
      seat.error = 'non_subscription_driver';
      seat.message = `Seat driver must be subscription CLI only; got ${d}`;
      return seat;
    }
  }

  // Raw HTTP grok driver name is forbidden for production seats
  if (coding_driver === 'grok' || review_driver === 'grok') {
    seat.ok = false;
    seat.error = 'xai_http_seat_forbidden';
    seat.message =
      'Production seats must use grok-cli subscription transport, not raw grok HTTP';
    return seat;
  }

  const productHits = findProductModelIds(seat);
  if (productHits.length) {
    seat.ok = false;
    seat.error = 'product_model_id_forbidden';
    seat.message = `Seat stamp must not carry product model IDs: ${productHits.join(', ')}`;
    seat.product_model_ids = productHits;
    return seat;
  }

  seat.ok = true;
  return seat;
}

export function buildCommission(input = {}) {
  const skill = normalizeCommissionSkill(input.skill);
  if (!skill) {
    return {
      ok: false,
      error: 'unknown_commission_skill',
      message: `Commission skill must be one of: ${COMMISSION_SKILLS.join(', ')}`,
      compose_only: true,
      allowed_skills: [...COMMISSION_SKILLS],
    };
  }

  const seats =
    input.seats && typeof input.seats === 'object'
      ? input.seats
      : resolveSeats({
          prefs: input.prefs ?? null,
          env: input.env,
          prefsPath: input.prefsPath,
          exists: input.exists,
          readFile: input.readFile,
        });

  if (seats.ok === false) {
    return {
      ok: false,
      error: seats.error ?? 'seat_resolution_failed',
      message: seats.message ?? 'Seat resolution failed for commission',
      compose_only: true,
      skill,
      seats,
    };
  }

  if (!isProductionSeatSafe(seats)) {
    return {
      ok: false,
      error: 'unsafe_production_seat',
      message:
        'Production seats must be subscription CLIs only (no product IDs, no XAI_API_KEY HTTP path)',
      compose_only: true,
      skill,
      seats,
    };
  }

  const depth_cell = input.depth_cell ?? input.depth ?? null;
  const active_effort = input.active_effort ?? null;
  const receipt_envelope =
    input.receipt_envelope ?? input.receipt ?? null;
  const commission_id =
    input.commission_id ??
    `ecgberht-commission-${skill}-${Date.now().toString(36)}`;

  // Spawn contract only — caller (host/orchestrator) may invoke the named skill.
  // Ecgberht never reimplements specialist loops here.
  return {
    ok: true,
    compose_only: true,
    kind: 'compose_spawn',
    skill,
    depth_cell,
    active_effort,
    receipt_envelope,
    commission_id,
    project_cwd: input.project_cwd ?? null,
    seats: {
      coding_family: seats.coding_family,
      review_family: seats.review_family,
      default_cli: seats.default_cli ?? null,
      coding_driver: seats.coding_driver,
      review_driver: seats.review_driver,
      cross_model: seats.cross_model,
      subscription_only: true,
      xai_http_seat: false,
      product_model_ids: [],
    },
    // Explicit negatives: adapters are hooks, not engines
    in_process_shark_tank: false,
    in_process_wave_loop: false,
    spawns_specialist: true,
    executes_in_process: false,
    product_model_ids: findProductModelIds(seats),
  };
}

export function interpretHandback(handback, meta = {}) {
  if (handback == null || typeof handback !== 'object' || Array.isArray(handback)) {
    return {
      ok: false,
      error: 'handback_not_object',
      message: 'Handback must be a structured object',
      receipt: null,
    };
  }

  const receipt = buildHandbackReceipt({
    as_of: handback.as_of ?? meta.as_of,
    active_effort: handback.active_effort,
    why_next: handback.why_next,
    grasscatch_why:
      handback.grasscatch_why !== undefined ? handback.grasscatch_why : null,
    tool_depth_why: handback.tool_depth_why,
    human_wait: handback.human_wait,
    uncertainty_flags: handback.uncertainty_flags,
    skill: handback.skill ?? meta.skill ?? null,
    depth: handback.depth ?? handback.depth_cell ?? meta.depth_cell ?? null,
    commission_id: handback.commission_id ?? meta.commission_id ?? null,
    partial: handback.partial === true,
  });

  const validated = validateReceipt(receipt);
  return {
    ok: validated.ok,
    error: validated.ok ? null : validated.error,
    message: validated.ok
      ? 'Handback validated as structured receipt'
      : validated.message,
    issues: validated.issues ?? [],
    receipt: validated.ok ? validated.receipt : receipt,
    validation: validated,
  };
}

export function confirmBoundCommission(opts = {}) {
  const proposal = opts.proposal;
  if (
    !proposal ||
    typeof proposal !== 'object' ||
    proposal.kind !== 'commission_proposal' ||
    proposal.requires_confirm !== true
  ) {
    return commissionFailure(COMMISSION_CODE.STATE_UNKNOWN, {
      error: 'commission_confirm_requires_proposal',
      message:
        'Confirm needs a steward commission_proposal (propose/confirm path — not a mode picker).',
    });
  }

  const who = normalizeWho(opts.who);
  if (!who) {
    return commissionFailure(COMMISSION_CODE.STATE_UNKNOWN, {
      error: 'commission_confirm_requires_who',
      message: 'Commission confirm is a human decision — pass who confirmed.',
      required: ['who'],
    });
  }

  // Auth via injected authorizer — never a token check inside the engine
  const authCtx = opts.authCtx ?? { principal: who.claimed };
  const decision = authorize('confirm', authCtx);
  if (!decision.ok) {
    return commissionFailure(COMMISSION_CODE.AUTH_REFUSED, {
      error: decision.code ?? 'auth-refused',
      message: decision.message ?? COMMISSION_TEXT[COMMISSION_CODE.AUTH_REFUSED],
      auth: decision,
      bind_appended: false,
      processes_launched: 0,
    });
  }

  // Hash-bound TOCTOU
  const expectedHash = recomputeProposalHash(proposal);
  const providedHash =
    opts.proposal_hash ?? proposal.proposal_hash ?? '';
  if (!providedHash || providedHash !== expectedHash) {
    return commissionFailure(COMMISSION_CODE.CONFIRM_HASH_MISMATCH, {
      error: 'confirm-hash-mismatch',
      presented_hash: providedHash || null,
      expected_hash: expectedHash,
      processes_launched: 0,
      bind_appended: false,
    });
  }

  const client_event_id =
    opts.client_event_id ??
    `confirm-${proposal.proposal_id ?? proposal.proposal_hash ?? 'anon'}`;

  // T-IDEM-11: double submit → original job_id, no second bind/launch
  const idemKey = opts.project_path
    ? `${path.resolve(opts.project_path)}::${client_event_id}`
    : `mem::${client_event_id}`;
  if (_idempotenceCache.has(idemKey)) {
    const prior = _idempotenceCache.get(idemKey);
    return {
      ...prior,
      ok: true,
      idempotent: true,
      already_confirmed: true,
      skip_write: true,
      second_bind: false,
      second_launch: false,
      processes_launched: 0,
      message: `Commission already confirmed (client_event_id=${client_event_id}); original job_id returned, no second bind or launch.`,
    };
  }

  const at = opts.at ?? todayIso();
  const job_id =
    opts.job_id ??
    `ecgberht-job-${String(proposal.skill).toLowerCase()}-${proposal.proposal_hash.slice(0, 10)}`;
  const commissioned_as = `${proposal.skill}:${job_id}`;

  let roadmap = opts.roadmap ?? null;
  let roadmap_event = null;
  let projection = null;
  let strip = opts.strip ?? null;
  let strip_appended = false;
  let strip_instrument = null;
  let durable = false;
  let confirm_journal = false;
  let sot_written = false;

  if (opts.project_path) {
    // Wave 7 confirm journal (spine path)
    const journaled = confirmCommissionJournaled({
      project_path: opts.project_path,
      proposal: { ...proposal, requires_confirm: true },
      roadmap,
      strip,
      who: who.claimed,
      at,
      job_id,
      client_event_id,
      project_id: opts.project_id ?? null,
      home: opts.home,
    });
    if (!journaled.ok && !journaled.killed) {
      return commissionFailure(COMMISSION_CODE.STATE_UNKNOWN, {
        error: journaled.error ?? 'confirm-journal-failed',
        message: journaled.message,
        detail: journaled,
      });
    }
    roadmap = journaled.roadmap ?? roadmap;
    roadmap_event = journaled.roadmap_event ?? null;
    projection = journaled.projection ?? null;
    strip = journaled.strip ?? strip;
    strip_appended = journaled.strip_appended === true;
    strip_instrument = journaled.strip_instrument ?? null;
    durable = true;
    confirm_journal = true;
    sot_written = journaled.ok === true && journaled.killed !== true;
  } else {
    // In-memory bind for dry-run / fixtures
    const bindEvent = {
      kind: 'commission_bind',
      step_id: proposal.step_id,
      commissioned_as,
      at,
      client_event_id,
      proposal_hash: expectedHash,
    };
    if (roadmap) {
      const bound = appendRoadmapEvent(roadmap, bindEvent, { at });
      if (!bound.ok) {
        return commissionFailure(COMMISSION_CODE.STATE_UNKNOWN, {
          error: bound.error ?? 'bind-failed',
          message: bound.message,
          detail: bound,
        });
      }
      roadmap = bound.roadmap;
      roadmap_event = bound.event;
      projection = bound.projection;
    }
    if (strip) {
      strip_instrument = {
        _kind: 'instrument',
        kind: 'commission_confirm',
        as_of: at,
        job_id,
        commission_id: proposal.commission?.commission_id ?? null,
        step_id: proposal.step_id,
        skill: proposal.skill,
        depth_cell: proposal.depth_cell ?? null,
        state: 'queued',
        who: who.claimed,
        client_event_id,
        proposal_hash: expectedHash,
      };
      const appended = appendStripInstrument(strip, strip_instrument, {
        apply_to_projection: false,
      });
      if (!appended.ok) {
        return commissionFailure(COMMISSION_CODE.STATE_UNKNOWN, {
          error: 'strip-append-failed',
          message: appended.message,
        });
      }
      strip = appended.strip;
      strip_appended = true;
    }
  }

  const job = {
    schema: JOB_SCHEMA_ID,
    job_id,
    commission_id: proposal.commission?.commission_id ?? null,
    proposal_id: proposal.proposal_id ?? null,
    proposal_hash: expectedHash,
    step_id: proposal.step_id,
    skill: proposal.skill,
    depth_cell: proposal.depth_cell ?? null,
    seat: proposal.seat ?? proposal.seats ?? null,
    estimate: proposal.estimate ?? null,
    confirmed_by: who,
    confirmed: true,
    runner: ANCHOR_JOB_COMPOSE.runner,
    compose: ANCHOR_JOB_COMPOSE,
    spawn: proposal.commission ?? null,
    state: 'queued',
    commissioned_as,
    lifecycle_events: [
      {
        seq: 1,
        from: null,
        to: 'queued',
        at,
        observed: 'commission_confirm',
        who: who.claimed,
      },
    ],
  };

  // Dossier: confirmation recorded; launch identity filled by executor
  let dossier = null;
  if (opts.project_path) {
    const up = upsertDossier(opts.project_path, {
      job_id,
      commissioned_as,
      proposal: {
        proposal_id: proposal.proposal_id,
        proposal_hash: expectedHash,
        skill: proposal.skill,
        step_id: proposal.step_id,
        depth_cell: proposal.depth_cell,
        seat: proposal.seat,
        estimate: proposal.estimate,
      },
      confirmation: {
        who,
        at,
        client_event_id,
        proposal_hash: expectedHash,
        confirmed: true,
      },
    });
    if (up.ok) dossier = up.dossier;
  } else {
    dossier = {
      ...emptyDossier(job_id, commissioned_as),
      proposal: {
        proposal_id: proposal.proposal_id,
        proposal_hash: expectedHash,
        skill: proposal.skill,
        step_id: proposal.step_id,
      },
      confirmation: {
        who,
        at,
        client_event_id,
        proposal_hash: expectedHash,
        confirmed: true,
      },
    };
  }

  // Executor seam — ONLY path to launch
  let executor_result = null;
  let launched = false;
  let confirmed_and_unlaunched = false;
  let no_executor_host = false;
  let processes_launched = 0;
  let pid = null;
  let proc_create_time = null;

  if (opts.skip_executor !== true) {
    executor_result = executeCommission(
      {
        ...job,
        confirmed: true,
        confirmation: dossier?.confirmation ?? { confirmed: true, who },
        dossier,
      },
      {
        confirmed: true,
        who,
        project_path: opts.project_path ?? null,
        // Launch-seam revalidation is opt-in via executor_ctx.authCtx (or a
        // direct executeCommission call). Do NOT auto-forward confirm authCtx:
        // confirm already authorized; Wave 19 launch refusals are proven on
        // the executeCommission path (auth outcome sweep), and auto-forward
        // would re-hit authorize('launch') on every confirm+launch.
        ...(opts.executor_ctx ?? {}),
      },
    );

    if (
      executor_result &&
      executor_result.code === COMMISSION_CODE.NO_EXECUTOR_HOST
    ) {
      no_executor_host = true;
      confirmed_and_unlaunched = true;
      launched = false;
      processes_launched = 0;
      // Preserve confirmed state by name on dossier
      if (opts.project_path && dossier) {
        upsertDossier(opts.project_path, {
          job_id,
          commissioned_as,
          confirmation: {
            ...(dossier.confirmation ?? {}),
            confirmed: true,
            launch_state: 'confirmed-and-unlaunched',
            no_executor_host: true,
          },
          launch: {
            state: 'confirmed-and-unlaunched',
            no_executor_host: true,
            pid: null,
            proc_create_time: null,
            at,
          },
        });
      } else if (dossier) {
        dossier.launch = {
          state: 'confirmed-and-unlaunched',
          no_executor_host: true,
          pid: null,
          proc_create_time: null,
          at,
        };
        dossier.confirmation = {
          ...(dossier.confirmation ?? {}),
          launch_state: 'confirmed-and-unlaunched',
          no_executor_host: true,
        };
      }
    } else if (executor_result && executor_result.ok !== false) {
      launched = executor_result.launched !== false;
      processes_launched = launched ? 1 : 0;
      pid = executor_result.pid ?? null;
      proc_create_time = executor_result.proc_create_time ?? null;
      if (launched && (pid != null || proc_create_time != null)) {
        if (opts.project_path) {
          recordLaunchOnDossier(opts.project_path, {
            job_id,
            commissioned_as,
            pid,
            proc_create_time,
            intent: executor_result.intent ?? { kind: 'launch_intent', at },
            at,
          });
        } else if (dossier) {
          dossier.launch = {
            pid,
            proc_create_time,
            at,
            intent: executor_result.intent ?? null,
          };
        }
      }
    }
  }

  const success = {
    ok: true,
    spelling: SPELLING,
    job,
    job_id,
    commissioned_as,
    who,
    proposal_hash: expectedHash,
    client_event_id,
    roadmap,
    roadmap_event,
    projection,
    strip,
    strip_appended,
    strip_instrument,
    dossier,
    durable,
    confirm_journal,
    sot_written,
    bind_appended: true,
    launched,
    processes_launched,
    pid,
    proc_create_time,
    confirmed_and_unlaunched,
    no_executor_host,
    silently_queued: false,
    executor_result,
    single_writer: ROADMAP_SINGLE_WRITER,
    compose: ANCHOR_JOB_COMPOSE,
    runner: ANCHOR_JOB_COMPOSE.runner,
    idempotent: false,
    already_confirmed: false,
    message: no_executor_host
      ? COMMISSION_TEXT[COMMISSION_CODE.NO_EXECUTOR_HOST]
      : `Commission confirmed by ${who.claimed}: ${commissioned_as} bound to step '${proposal.step_id}'${launched ? ' and launched' : ' (queued)'}.`,
  };

  // When no-executor-host, surface the named code while keeping ok-ish confirmed state
  if (no_executor_host) {
    const named = {
      ...success,
      // Confirmed succeeded; launch refused by name — dual status
      ok: true,
      code: COMMISSION_CODE.NO_EXECUTOR_HOST,
      status: COMMISSION_CODE.NO_EXECUTOR_HOST,
      status_code: COMMISSION_CODE.NO_EXECUTOR_HOST,
      text: COMMISSION_TEXT[COMMISSION_CODE.NO_EXECUTOR_HOST],
      user_text: COMMISSION_TEXT[COMMISSION_CODE.NO_EXECUTOR_HOST],
      confirmed: true,
      launched: false,
    };
    _idempotenceCache.set(idemKey, named);
    return named;
  }

  _idempotenceCache.set(idemKey, success);
  return success;
}

export function assemblePortfolioGlance(opts = {}) {
  const inject = opts.inject ?? {};
  const degraded = [];

  // Injected rows (tests / pure fold)
  if (Array.isArray(inject.rows)) {
    const rows = [...inject.rows];
    for (const s of opts.skipped_roots ?? inject.skipped_roots ?? []) {
      const pathStr = typeof s === 'string' ? s : s?.project_path ?? s?.root ?? '';
      if (!pathStr) continue;
      rows.push(
        buildGlanceRow({
          project_id: typeof s === 'object' ? s.project_id ?? null : null,
          project_path: pathStr,
          label: typeof s === 'object' ? s.label ?? pathStr : pathStr,
          skipped: true,
        }),
      );
    }
    for (const u of opts.unreadable_projects ?? inject.unreadable_projects ?? []) {
      const already = rows.some(
        (r) =>
          (u.project_id && r.project_id === u.project_id) ||
          (u.project_path && r.project_path === u.project_path),
      );
      if (already) continue;
      rows.push(
        buildGlanceRow({
          project_id: u.project_id ?? null,
          project_path: u.project_path ?? null,
          label: u.label ?? u.project_id ?? u.project_path,
          unreadable: true,
        }),
      );
    }
    if (rows.length > PORTFOLIO_MAX_ROWS) {
      return boundExceededResult(rows.length);
    }
    const folded = foldProjections(rows, inject);
    for (const row of rows) {
      for (const f of CRITERION_13_FIELDS) {
        if (row.fields?.[f]?.known === false) {
          degraded.push(
            Object.freeze({
              project_id: row.project_id,
              field: f,
              mark: COMPOSITE.DEGRADED,
              note: 'A5 field beyond cap / absent in index — named unknown; Wave 19 kill gate cannot green criterion 13 on DEGRADED without signed decision',
            }),
          );
        }
      }
    }
    return Object.freeze({
      ok: true,
      schema: GLANCE_SCHEMA,
      rows: Object.freeze(rows),
      row_count: rows.length,
      ...folded,
      write_authority: 'none',
      discoverStrips_reached: false,
      degraded: Object.freeze(degraded),
      ambient: ambientSignals(folded.badge),
      field_coverage: Object.freeze({
        keys: GLANCE_FIELD_KEYS,
        every_row_complete: rows.every((r) => r.field_coverage_complete === true),
      }),
    });
  }

  let home = opts.home ?? inject.home ?? null;
  let paths;
  try {
    paths = opts.paths ?? inject.paths ?? indexPathsFrom({
      home: opts.home,
      env: opts.env ?? inject.env,
      paths: opts.paths,
    });
    home = paths.home;
  } catch (e) {
    return Object.freeze({
      ok: false,
      schema: GLANCE_SCHEMA,
      error: GLANCE_CODE.GLANCE_INDEX_MISSING,
      code: GLANCE_CODE.GLANCE_INDEX_MISSING,
      message: GLANCE_TEXT[GLANCE_CODE.GLANCE_INDEX_MISSING],
      detail: String(e?.message ?? e),
      rows: Object.freeze([]),
      row_count: 0,
      discoverStrips_reached: false,
      write_authority: 'none',
    });
  }

  if (!home || !fs.existsSync(home)) {
    return Object.freeze({
      ok: false,
      schema: GLANCE_SCHEMA,
      error: GLANCE_CODE.GLANCE_INDEX_MISSING,
      code: GLANCE_CODE.GLANCE_INDEX_MISSING,
      message: GLANCE_TEXT[GLANCE_CODE.GLANCE_INDEX_MISSING],
      rows: Object.freeze([]),
      row_count: 0,
      discoverStrips_reached: false,
      write_authority: 'none',
    });
  }

  const journal = newReadJournal();
  journal.writes = [];
  const guarded = glanceIndexOnlyFs(opts.fsx ?? fs, home, journal);

  let read;
  try {
    read = openIndexForRead({ ...opts, paths, home, fsx: guarded, env: opts.env ?? inject.env });
  } catch (e) {
    if (e instanceof QueryRefusal) {
      return Object.freeze({
        ok: false,
        schema: GLANCE_SCHEMA,
        error: GLANCE_CODE.GLANCE_QUERY_REFUSED,
        code: GLANCE_CODE.GLANCE_QUERY_REFUSED,
        message: GLANCE_TEXT[GLANCE_CODE.GLANCE_QUERY_REFUSED],
        detail: e.message,
        rows: Object.freeze([]),
        row_count: 0,
        discoverStrips_reached: false,
        no_walk: noWalkReceipt(journal),
        write_authority: 'none',
      });
    }
    return Object.freeze({
      ok: false,
      schema: GLANCE_SCHEMA,
      error: GLANCE_CODE.GLANCE_INDEX_UNPARSEABLE,
      code: GLANCE_CODE.GLANCE_INDEX_UNPARSEABLE,
      message: GLANCE_TEXT[GLANCE_CODE.GLANCE_INDEX_UNPARSEABLE],
      detail: String(e?.message ?? e),
      rows: Object.freeze([]),
      row_count: 0,
      discoverStrips_reached: false,
      no_walk: noWalkReceipt(journal),
      write_authority: 'none',
    });
  }

  if (read.ok !== true) {
    // Distinguish missing vs unparseable
    const code =
      read.code === 'INDEX_ABSENT' || read.reason === 'absent'
        ? GLANCE_CODE.GLANCE_INDEX_MISSING
        : GLANCE_CODE.GLANCE_INDEX_UNPARSEABLE;
    return Object.freeze({
      ok: false,
      schema: GLANCE_SCHEMA,
      error: code,
      code,
      message: GLANCE_TEXT[code],
      detail: read.reason ?? read.text ?? null,
      rows: Object.freeze([]),
      row_count: 0,
      discoverStrips_reached: false,
      no_walk: noWalkReceipt(journal),
      write_authority: 'none',
    });
  }

  const events = replayEvents(read.events ?? []);
  const registry = materializeRegistry(events);
  const snapshot = read.snapshot_value && typeof read.snapshot_value === 'object'
    ? read.snapshot_value
    : null;
  const freshness = snapshot?.freshness && typeof snapshot.freshness === 'object'
    ? snapshot.freshness
    : { per_project: {} };
  const perProject = freshness.per_project && typeof freshness.per_project === 'object'
    ? freshness.per_project
    : {};

  // Body rows by project for stage binding
  const bodyRows = [];
  if (snapshot?.body && typeof snapshot.body === 'object') {
    const projects = snapshot.body.projects ?? snapshot.body;
    // body shape varies — collect derived-like arrays if present
    if (Array.isArray(snapshot.body.rows)) bodyRows.push(...snapshot.body.rows);
  }

  const attentionCells = listAttentionCellsFromIndex({ home, fsx: guarded, journal });
  const attentionById = new Map();
  const attentionByPath = new Map();
  for (const c of attentionCells) {
    if (c.project_id) attentionById.set(String(c.project_id), c);
    if (c.key) attentionById.set(String(c.key), c);
    // Option-P path passport: a cell pushed by the HOST carries the host's
    // project id (Anchor's), which is not the steward registry's id — found
    // live 2026-08-06: a real needs_you cell folded to queue 0. The resolved
    // project path is the identity both sides share. NEWEST WINS when several
    // ids pushed cells for one path (1 folder : N host projects is legal) —
    // otherwise a stale cell can shadow a live raise.
    if (c.project_path) {
      const key = path.resolve(String(c.project_path));
      const prev = attentionByPath.get(key);
      if (!prev || String(c.at ?? '') >= String(prev.at ?? '')) {
        attentionByPath.set(key, c);
      }
    }
  }

  const rows = [];
  const projects = Array.isArray(registry.projects) ? registry.projects : [];

  for (const p of projects) {
    const pid = p.project_id;
    const fresh = perProject[pid] ?? null;
    const rowPath = p.current_path ?? p.root ?? null;
    const att =
      attentionById.get(String(pid)) ??
      (rowPath ? attentionByPath.get(path.resolve(String(rowPath))) : null) ??
      null;
    // Presence UNREACHABLE / unreadable store → unknown row kept.
    //
    // EXCEPT (2026-08-06, found live): UNREACHABLE means "nobody has checked
    // the filesystem yet", not "the root is gone" — and a LIVE attention cell
    // pushed by the project moments ago is itself evidence. Zeroing the row
    // threw away a real needs_you: the ⚑ badge (which reads cells directly)
    // said 1 while the raise queue said 0 — the two surfaces disagreeing about
    // the same fact. ABSENT (checked and gone) still marks the row unreadable.
    const presence = fresh?.presence ?? p.presence ?? null;
    const unreadable =
      (presence === PRESENCE.UNREACHABLE && att == null) ||
      presence === PRESENCE.ABSENT ||
      presence === 'unreadable' ||
      p.unreadable === true;

    const derivedForProject = bodyRows.filter(
      (r) => r && String(r.project_id) === String(pid),
    );

    const row = buildGlanceRow({
      project_id: pid,
      project_path: p.current_path ?? p.root ?? null,
      label: p.label ?? pid,
      fresh,
      attention: att
        ? {
            state: att.state,
            reason: att.reason,
            waiting_steps: att.waiting_steps,
            briefing: att.briefing ?? null,
          }
        : null,
      derived_rows: derivedForProject,
      unreadable,
    });

    // DEGRADED: any A5 field still unknown ships named + gate-report entry
    for (const f of CRITERION_13_FIELDS) {
      if (row.fields[f]?.known === false) {
        degraded.push(
          Object.freeze({
            project_id: pid,
            field: f,
            mark: COMPOSITE.DEGRADED,
            note: 'A5 field beyond cap / absent in index — named unknown; Wave 19 kill gate cannot green criterion 13 on DEGRADED without signed decision',
          }),
        );
      }
    }
    rows.push(row);
  }

  // Unreadable projects supplied explicitly (not in registry)
  for (const u of opts.unreadable_projects ?? inject.unreadable_projects ?? []) {
    const already = rows.some(
      (r) =>
        (u.project_id && r.project_id === u.project_id) ||
        (u.project_path && r.project_path === u.project_path),
    );
    if (already) continue;
    rows.push(
      buildGlanceRow({
        project_id: u.project_id ?? null,
        project_path: u.project_path ?? null,
        label: u.label ?? u.project_id ?? u.project_path,
        unreadable: true,
      }),
    );
  }

  // Semicolon-skipped roots → unknown rows (row count never shrinks)
  const skipped = [
    ...(opts.skipped_roots ?? []),
    ...(inject.skipped_roots ?? []),
  ];
  for (const s of skipped) {
    const pathStr = typeof s === 'string' ? s : s?.project_path ?? s?.root ?? '';
    if (!pathStr) continue;
    rows.push(
      buildGlanceRow({
        project_id: typeof s === 'object' ? s.project_id ?? null : null,
        project_path: pathStr,
        label: typeof s === 'object' ? s.label ?? pathStr : pathStr,
        skipped: true,
      }),
    );
  }

  if (rows.length > PORTFOLIO_MAX_ROWS) {
    return boundExceededResult(rows.length, journal);
  }

  if (rows.length === 0) {
    return Object.freeze({
      ok: true,
      schema: GLANCE_SCHEMA,
      code: GLANCE_CODE.GLANCE_PORTFOLIO_EMPTY,
      message: GLANCE_TEXT[GLANCE_CODE.GLANCE_PORTFOLIO_EMPTY],
      rows: Object.freeze([]),
      row_count: 0,
      items: Object.freeze([]),
      badge: Object.freeze({
        glyph: '⚑',
        count: 0,
        only_ambient_signal: true,
      }),
      queue_length: 0,
      empty: true,
      discoverStrips_reached: false,
      no_walk: noWalkReceipt(journal),
      write_authority: 'none',
      writes_attempted: journal.writes.length,
      degraded: Object.freeze(degraded),
      ambient: ambientSignals({ count: 0 }),
      files_opened: journal.total,
    });
  }

  const folded = foldProjections(rows, inject);

  // Refresh badge cache so the next poll is cache-hit cheap
  try {
    writeBadgeCache({
      home,
      count: folded.queue_length,
      projects: folded.raise_queue.queue
        .map((q) => q.project_id)
        .filter(Boolean),
      updated_via: 'assemblePortfolioGlance',
      fsx: fs,
    });
  } catch {
    // Cache refresh failure does not fail the glance read.
  }

  return Object.freeze({
    ok: true,
    schema: GLANCE_SCHEMA,
    home,
    rows: Object.freeze(rows),
    row_count: rows.length,
    items: folded.items,
    raise_queue: folded.raise_queue,
    badge: folded.badge,
    queue_length: folded.queue_length,
    discoverStrips_reached: false,
    walk_path_unreachable: true,
    no_walk: noWalkReceipt(journal),
    write_authority: 'none',
    writes_attempted: journal.writes.length,
    degraded: Object.freeze(degraded),
    ambient: ambientSignals(folded.badge),
    files_opened: journal.total,
    field_coverage: Object.freeze({
      keys: GLANCE_FIELD_KEYS,
      every_row_complete: rows.every((r) => r.field_coverage_complete === true),
    }),
  });
}

export function buildRaiseQueue(items = [], opts = {}) {
  const threshold =
    typeof opts.starve_threshold_days === 'number'
      ? opts.starve_threshold_days
      : STARVE_THRESHOLD_DAYS_DEFAULT;

  const scored = (Array.isArray(items) ? items : []).map((item) => {
    const severity = raiseSeverity(item);
    const age =
      typeof item.anti_starvation_age_days === 'number'
        ? item.anti_starvation_age_days
        : 0;
    const humanish =
      (nonEmpty(item.human_wait) && item.human_wait !== 'none') ||
      (typeof item.waiting_steps === 'number' && item.waiting_steps > 0);
    const age_bumped = humanish && age >= threshold;
    if (age_bumped) severity.reasons.push(`age_bump>=${threshold}d`);
    return { ...item, severity, age_bumped };
  });

  // Queue membership: anything below ambient severity, plus age-bumped
  // campaigns that must enter regardless of tier.
  const queue = scored
    .filter(
      (s) => s.severity.tier < RAISE_SEVERITY_TIERS.ambient || s.age_bumped,
    )
    .sort((a, b) => {
      if (a.severity.tier !== b.severity.tier) return a.severity.tier - b.severity.tier;
      const ageA = a.anti_starvation_age_days ?? 0;
      const ageB = b.anti_starvation_age_days ?? 0;
      if (ageB !== ageA) return ageB - ageA; // older first among equals
      return String(a.project_id ?? a.project_path ?? '').localeCompare(
        String(b.project_id ?? b.project_path ?? ''),
      );
    });

  return {
    queue,
    raised: queue[0] ?? null,
    queue_length: queue.length,
    max_raised: MAX_RAISED_BLOCKS,
    badge: {
      glyph: '⚑',
      count: queue.length,
      only_ambient_signal: true,
      law: '⚑ count equals raise queue length; no other ambient notification surfaces anywhere in Anchor',
    },
    starve_threshold_days: threshold,
  };
}

export function demandClose(root, base, step_id, goal_reread) {
  const closing = closeOf({ kind: 'status_flip', to: 'done', step_id, goal_reread }, base);
  if (!closing) return { ok: true, demanded: false };
  const demand = demandSpineForClose(root, base, step_id);
  if (!demand.ok) return demand;
  if (!GOAL_REREAD.includes(goal_reread)) {
    return {
      ok: false, error: 'goal_reread_required', closing: step_id,
      message: 'Close refused: re-read the North Star and say so - --goal-reread reaffirmed|rewritten '
        + '(or goal_reread on the refinement close operation); the engine records the goal_flip.',
    };
  }
  return { ok: true, demanded: true };
}

export function verbRefinementUpdate(opts={}) {
  try {
    const input=opts.refinement_operation || JSON.parse(fs.readFileSync(0,'utf8'));
    if(input.action==='capabilities') return {ok:true,capabilities:{schema:REFINEMENT_SCHEMA,version:1,
      actions:['producer_handoff','resolve_handoff','visual_companion'],
      individual_completion:true,approved_collection:true,provisional_publish:true}};
    const root=path.resolve(opts.project || '.');
    const loaded=loadProjectRoadmap(root);
    if(!loaded.ok || !loaded.exists) return fail(loaded.exists?'backing-store-unreadable':'empty-but-valid');
    if(input.action==='read') return refinementResult(root,loaded.roadmap);
    if(input.action==='repair') {
      return repairRoadmapProjectionsThroughSpine(root,{timeoutMs:opts.timeoutMs});
    }
    if(input.action==='operation_status') {
      const found=loaded.roadmap.roadmap_events.find(e=>e.kind==='refinement_update'&&e.operation?.operation_id===input.operation_id);
      const result=refinementResult(root,loaded.roadmap);
      return {...result,operation_id:input.operation_id,committed:!!found,result:found?{...result,committed:true,operation_id:input.operation_id}:undefined};
    }
    if(!input.operation_id || !Number.isInteger(input.expected_seq)) return fail('operation-id-and-sequence-required');
    if(input.action==='close') {
      // cockpit Wave B: the steward's close states the next act and the goal re-read first
      const demand=demandClose(root,loaded.roadmap,input.step_id,input.goal_reread??null);
      if(!demand.ok) return demand;
    }
